import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

def compact_schema(s, indent=0):
    if not isinstance(s, dict):
        return str(s)
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    t = s.get('type', '')
    if t == 'object' or 'properties' in s:
        props = s.get('properties', {})
        req = set(s.get('required', []))
        lines = ['{']
        for k, v in props.items():
            mark = '*' if k in req else ''
            extra = ''
            if isinstance(v, dict):
                if 'enum' in v:
                    extra = f" enum={v['enum']}"
                if 'format' in v:
                    extra = f" {v['format']}" + extra
                if 'default' in v:
                    extra += f" default={v['default']}"
                if 'minimum' in v:
                    extra += f" min={v['minimum']}"
                if 'maximum' in v:
                    extra += f" max={v['maximum']}"
                if v.get('type') == 'array':
                    items = v.get('items', {})
                    extra += f"[]{compact_schema(items) if isinstance(items, dict) and ('$ref' in items or items.get('type')!='object') else compact_schema(items)}"
                    lines.append(f"  {k}{mark}: array{extra}")
                    continue
                if 'allOf' in v:
                    extra += ' allOf=' + ','.join(compact_schema(x) for x in v['allOf'])
            lines.append(f"  {k}{mark}: {compact_schema(v) if isinstance(v, dict) and (v.get('type')=='object' or 'properties' in v or 'oneOf' in v) else v.get('type','?') if isinstance(v, dict) else v}{extra}")
        if s.get('additionalProperties') is True:
            lines.append('  [additional]')
        elif s.get('additionalProperties') is False:
            lines.append('  [strict]')
        elif isinstance(s.get('additionalProperties'), dict):
            lines.append(f"  [additional: {compact_schema(s['additionalProperties'])}]")
        lines.append('}')
        return '\n'.join(lines)
    if 'oneOf' in s:
        return 'oneOf(' + ', '.join(compact_schema(x) for x in s['oneOf']) + ')'
    if t == 'array':
        return f"array[{compact_schema(s.get('items', {}))}]"
    return t

for path, methods in spec['paths'].items():
    for method, op in methods.items():
        if method.startswith('x-'): continue
        print('='*80)
        print(f"{method.upper()} {path}  [{op.get('operationId')}]")
        sec = op.get('security', 'default')
        print(f"  security: {sec}")
        params = op.get('parameters', [])
        if params:
            print(f"  params:")
            for p in params:
                print(f"    {p.get('name')} in={p.get('in')} required={p.get('required')} schema={p.get('schema')}")
        rb = op.get('requestBody')
        if rb:
            schema = rb.get('content', {}).get('application/json', {}).get('schema', {})
            print(f"  REQUEST (required={rb.get('required')}):")
            print(compact_schema(schema))
        print("  RESPONSES:")
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content', {})
            for ct, cval in content.items():
                schema = cval.get('schema', {})
                print(f"    {code}:")
                print(compact_schema(schema))
        print()
