// ---------- locations / connections ----------

func (s *Store) InsertLocation(ctx context.Context, l Location) error {
	_, err := s.PG.Exec(ctx, `
		INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
