package main

import (
	"context"
	"io/fs"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/google/uuid"
	"golang.org/x/crypto/bcrypt"
)

type App struct {
	Store  *Store
	snapMu sync.Mutex
}

func main() {
	ctx := context.Background()
	store, err := Connect(ctx)
	if err != nil {
		log.Fatalf("connect: %v", err)
	}
	defer store.Close()

	schema, err := os.ReadFile(findSchema())
	if err != nil {
		log.Fatalf("schema: %v", err)
	}
	// Ensure schema exists (idempotent CREATE IF NOT EXISTS)
	if err := store.ApplySchema(ctx, string(schema)); err != nil {
		log.Fatalf("apply schema: %v", err)
	}
	if err := store.MaterializeMongo(ctx); err != nil {
		log.Fatalf("mongo: %v", err)
	}
	// seed sample types if empty
	types, _ := store.ListSampleTypes(ctx)
	if len(types) == 0 {
		if err := seedDefaultSampleTypes(ctx, store); err != nil {
			log.Fatalf("seed types: %v", err)
		}
	}

	app := &App{Store: store}
	if err := app.ensureAdmin(ctx); err != nil {
		log.Fatalf("admin: %v", err)
	}
	app.rebuildServiceabilitySnapshot(ctx)

	go app.offerLoop()

	mux := http.NewServeMux()
	app.routes(mux)

	addr := "127.0.0.1:8080"
	if p := os.Getenv("LISTEN_ADDR"); p != "" {
		addr = p
	}
	log.Printf("listening on http://%s", addr)
	if err := http.ListenAndServe(addr, cors(mux)); err != nil {
		log.Fatal(err)
	}
}

func findSchema() string {
	cands := []string{
		"schema.sql",
		"backend/schema.sql",
		"/workspace/backend/schema.sql",
	}
	if exe, err := os.Executable(); err == nil {
		cands = append([]string{filepath.Join(filepath.Dir(exe), "schema.sql")}, cands...)
	}
	for _, c := range cands {
		if _, err := os.Stat(c); err == nil {
			return c
		}
	}
	return "schema.sql"
}

func (app *App) ensureAdmin(ctx context.Context) error {
	n, err := app.Store.CountUsers(ctx)
	if err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	user := os.Getenv("ADMIN_USERNAME")
	pass := os.Getenv("ADMIN_PASSWORD")
	if user == "" || pass == "" {
		log.Printf("no users and ADMIN_USERNAME/ADMIN_PASSWORD not set; waiting for first start with credentials")
		return nil
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(pass), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	u := User{
		ID: uuid.New(), Username: user, PasswordHash: string(hash),
		FullName: "Administrator", Roles: []string{RoleAdministrator},
		Active: true, Available: true, CapacityUnits: 0,
	}
	if err := app.Store.InsertUser(ctx, u); err != nil {
		return err
	}
	log.Printf("created initial administrator %s", user)
	return nil
}

func (app *App) offerLoop() {
	t := time.NewTicker(15 * time.Second)
	defer t.Stop()
	for range t.C {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		app.expireAndReoffer(ctx)
		cancel()
	}
}

func (app *App) expireAndReoffer(ctx context.Context) {
	asgs, err := app.Store.ListOpenOffered(ctx)
	if err != nil {
		return
	}
	now := time.Now().UTC()
	for _, a := range asgs {
		if a.OfferExpiresAt != nil && now.After(*a.OfferExpiresAt) {
			if a.OfferedTo != nil {
				_ = app.Store.BumpDecline(ctx, *a.OfferedTo)
			}
			a.OfferedTo = nil
			a.OfferExpiresAt = nil
			_ = app.Store.UpdateAssignment(ctx, a)
			sm, _ := app.Store.GetSample(ctx, a.SampleID)
			if sm == nil {
				continue
			}
			st, _ := app.Store.GetSampleType(ctx, sm.SampleTypeID)
			all, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
			_ = app.offerNext(ctx, sm, all, st)
			// if still no worker after long time, exception
			if sm.CreatedAtZero() {
				continue
			}
		}
	}
	// flag samples with unoffered required assignments for too long
	samples, _ := app.Store.ListSamples(ctx)
	for _, sm := range samples {
		if sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired || sm.Status == StatusException || sm.Status == StatusUnserviceable {
			continue
		}
		asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
		for _, a := range asgs {
			if a.Status == StatusPending && a.OfferedTo == nil && a.Kind == KindCollection {
				// created long ago?
				st, _ := app.Store.GetSampleType(ctx, sm.SampleTypeID)
				if st != nil && st.QualifiedCollectorRequired {
					// try offer again
					_ = app.offerNext(ctx, &sm, asgs, st)
					// if still none, check age via first timeline? use requested_at
					if time.Since(sm.RequestedAt) > NoWorkerTimeout {
						sm.Status = StatusException
						sm.Exception = map[string]interface{}{"reason": "no_qualified_worker", "assignmentId": a.ID.String()}
						_ = app.Store.UpdateSample(ctx, sm)
						app.writeAudit(ctx, "system", "system", "exception", "sample", sm.ID.String(), true, sm.Exception)
					}
				}
			}
		}
	}
}

func (s Sample) CreatedAtZero() bool { return false }

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func (app *App) routes(mux *http.ServeMux) {
	mux.HandleFunc("GET /ready", app.handleReady)

	mux.HandleFunc("POST /api/authenticate-user", app.handleLogin)
	mux.HandleFunc("POST /api/select-active-role", app.withAuth(app.handleSelectRole))
	mux.HandleFunc("POST /api/create-user", app.withAuth(app.handleCreateUser))
	mux.HandleFunc("POST /api/update-user-access", app.withAuth(app.handleUpdateUserAccess))
	mux.HandleFunc("GET /api/read-user/{userId}", app.withAuth(app.handleReadUser))

	mux.HandleFunc("POST /api/create-sample-type", app.withAuth(app.handleCreateSampleType))
	mux.HandleFunc("POST /api/update-sample-type", app.withAuth(app.handleUpdateSampleType))
	mux.HandleFunc("POST /api/create-location", app.withAuth(app.handleCreateLocation))
	mux.HandleFunc("POST /api/update-location", app.withAuth(app.handleUpdateLocation))
	mux.HandleFunc("POST /api/set-location-status", app.withAuth(app.handleSetLocationStatus))
	mux.HandleFunc("POST /api/set-location-function-status", app.withAuth(app.handleSetLocationFunction))
	mux.HandleFunc("POST /api/create-connection", app.withAuth(app.handleCreateConnection))
	mux.HandleFunc("POST /api/set-connection-status", app.withAuth(app.handleSetConnectionStatus))
	mux.HandleFunc("POST /api/configure-capacity", app.withAuth(app.handleConfigureCapacity))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", app.withAuth(app.handleConfigureLabAcceptance))
	mux.HandleFunc("POST /api/set-worker-availability", app.withAuth(app.handleSetWorkerAvailability))

	mux.HandleFunc("POST /api/check-serviceability", app.withAuth(app.handleCheckServiceability))
	mux.HandleFunc("POST /api/read-serviceability-snapshot", app.withAuth(app.handleReadSnapshot))
	mux.HandleFunc("POST /api/create-collection-request", app.withAuth(app.handleCreateRequest))
	mux.HandleFunc("POST /api/ingest-presealed-sample", app.withAuth(app.handleIngestPresealed))

	mux.HandleFunc("POST /api/accept-assignment", app.withAuth(app.withIdempotency("accept-assignment", app.handleAccept)))
	mux.HandleFunc("POST /api/decline-assignment", app.withAuth(app.withIdempotency("decline-assignment", app.handleDecline)))
	mux.HandleFunc("POST /api/collect-and-seal-sample", app.withAuth(app.withIdempotency("collect-and-seal", app.handleCollectSeal)))
	mux.HandleFunc("POST /api/initiate-handoff", app.withAuth(app.withIdempotency("initiate-handoff", app.handleInitiateHandoff)))
	mux.HandleFunc("POST /api/confirm-handoff", app.withAuth(app.withIdempotency("confirm-handoff", app.handleConfirmHandoff)))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", app.withAuth(app.withIdempotency("confirm-receipt", app.handleConfirmReceipt)))
	mux.HandleFunc("POST /api/record-laboratory-exception", app.withAuth(app.withIdempotency("lab-exception", app.handleLabException)))
	mux.HandleFunc("POST /api/record-handling-checkpoint", app.withAuth(app.withIdempotency("checkpoint", app.handleCheckpoint)))
	mux.HandleFunc("POST /api/record-worker-location", app.withAuth(app.handleRecordLocation))
	mux.HandleFunc("POST /api/update-assignment-progress", app.withAuth(app.withIdempotency("progress", app.handleProgress)))

	mux.HandleFunc("POST /api/list-role-work", app.withAuth(app.handleListRoleWork))
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", app.withAuth(app.handleReadSampleState))
	mux.HandleFunc("POST /api/read-sample-lifecycle", app.withAuth(app.handleReadLifecycle))
	mux.HandleFunc("POST /api/read-journey-plan", app.withAuth(app.handleReadJourney))
	mux.HandleFunc("POST /api/read-operations-state", app.withAuth(app.handleOpsState))
	mux.HandleFunc("GET /api/ui/bootstrap", app.withAuth(app.handleBootstrap))
	mux.HandleFunc("GET /api/events", app.withAuth(app.handleEvents))
	mux.HandleFunc("POST /api/search-audit-trail", app.withAuth(app.handleSearchAudit))

	mux.HandleFunc("POST /api/cancel-journey", app.withAuth(app.withIdempotency("cancel-journey", app.handleCancelJourney)))
	mux.HandleFunc("POST /api/reroute-journey", app.withAuth(app.withIdempotency("reroute-journey", app.handleReroute)))
	mux.HandleFunc("POST /api/split-journey", app.withAuth(app.withIdempotency("split-journey", app.handleSplit)))
	mux.HandleFunc("POST /api/merge-journeys", app.withAuth(app.withIdempotency("merge-journeys", app.handleMerge)))
	mux.HandleFunc("POST /api/edit-active-plan", app.withAuth(app.withIdempotency("edit-plan", app.handleEditPlan)))
	mux.HandleFunc("POST /api/report-disruption", app.withAuth(app.withIdempotency("disruption", app.handleDisruption)))

	// static frontend + map assets
	mapDir := "/opt/arena/map-assets"
	mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir))))

	webDir := findWebDir()
	if webDir != "" {
		mux.HandleFunc("/", spaHandler(webDir))
	} else {
		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path == "/" {
				w.Header().Set("Content-Type", "text/plain")
				_, _ = w.Write([]byte("Lab Sample Pickup & Delivery API"))
				return
			}
			http.NotFound(w, r)
		})
	}
}

func findWebDir() string {
	cands := []string{"/workspace/frontend/dist", "frontend/dist", "/workspace/web"}
	for _, c := range cands {
		if st, err := os.Stat(c); err == nil && st.IsDir() {
			return c
		}
	}
	return ""
}

func spaHandler(dir string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/api/") || r.URL.Path == "/ready" {
			http.NotFound(w, r)
			return
		}
		p := filepath.Join(dir, filepath.Clean(r.URL.Path))
		if !strings.HasPrefix(p, dir) {
			http.NotFound(w, r)
			return
		}
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			http.ServeFile(w, r, p)
			return
		}
		index := filepath.Join(dir, "index.html")
		if _, err := os.Stat(index); err == nil {
			http.ServeFile(w, r, index)
			return
		}
		http.NotFound(w, r)
	}
}

func _unusedFS(fs.FS) {}

