	labID, err1 := uuid.Parse(req.LaboratoryID)
	tid, err2 := uuid.Parse(req.SampleTypeID)
	if err1 != nil || err2 != nil {
		writeErr(w, 400, "invalid_acceptance", "invalid ids")
		return
	}
	lab, _ := app.Store.GetLocation(r.Context(), labID)
	st, _ := app.Store.GetSampleType(r.Context(), tid)
	if lab == nil || st == nil || !lab.Functions.Laboratory {
		writeErr(w, 400, "invalid_acceptance", "invalid laboratory or type")
		return
	}
	id, err := app.Store.UpsertLabAcceptance(r.Context(), labID, tid, req.Accepts)
	if err != nil {
		writeErr(w, 500, "internal_error", "save")
		return
	}
	_, _ = app.Store.BumpNetworkRevision(r.Context())
	go app.rebuildServiceabilitySnapshot(context.Background())
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "configure_laboratory_acceptance", "laboratory", labID.String(), true, map[string]interface{}{"sampleTypeId": tid.String(), "accepts": req.Accepts})
	writeData(w, 200, map[string]any{"acceptanceId": id.String(), "accepts": req.Accepts})
}

