		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		ConnectionID string `json:"connectionId"`
		Active       bool   `json:"active"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	id, err := uuid.Parse(req.ConnectionID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	c, _ := app.Store.GetConnection(r.Context(), id)
	if c == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if err := app.Store.SetConnectionActive(r.Context(), id, req.Active); err != nil {
		writeErr(w, 500, "internal_error", "update")
		return
	}
	_, _ = app.Store.BumpNetworkRevision(r.Context())
	go app.rebuildServiceabilitySnapshot(context.Background())
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "set_connection_status", "connection", id.String(), true, map[string]interface{}{"active": req.Active})
	writeData(w, 200, map[string]any{"connectionId": id.String(), "active": req.Active})
}

func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	// admin always; node handler / lab team for their assigned location
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.CapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "invalid capacity")
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		if *req.CooledCapacityUnits < 0 {
			writeErr(w, 400, "invalid_capacity", "invalid cooled capacity")
			return
		}
		cooled = *req.CooledCapacityUnits
	}
	rid, err := uuid.Parse(req.ResourceID)
	if err != nil {
		writeErr(w, 400, "invalid_json", "invalid resource")
		return
	}
	loc, _ := app.Store.GetLocation(r.Context(), rid)
	conn, _ := app.Store.GetConnection(r.Context(), rid)
	if loc == nil && conn == nil {
		writeErr(w, 400, "invalid_capacity", "unknown resource")
		return
	}
	allowed := requireRole(auth, RoleAdministrator)
	if !allowed && requireRole(auth, RoleNodeHandler, RoleLaboratoryTeam) {
		if loc != nil && auth.User.AssignedLocationID != nil && *auth.User.AssignedLocationID == loc.ID {
			allowed = true
		}
	}
	if !allowed {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	// refuse reducing below reserved
	if loc != nil {
		if req.CapacityUnits < loc.ReservedUnits || cooled < loc.CooledReserved {
			writeErr(w, 409, "capacity_reserved", "capacity reserved")
			return
		}
	}
	if conn != nil {
		if req.CapacityUnits < conn.ReservedUnits || cooled < conn.CooledReserved {
			writeErr(w, 409, "capacity_reserved", "capacity reserved")
			return
		}
	}
	kind, err := app.Store.ConfigureCapacity(r.Context(), rid, req.CapacityUnits, cooled)
	if err != nil || kind == "" {
		writeErr(w, 500, "internal_error", "update")
		return
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "configure_capacity", kind, rid.String(), true, map[string]interface{}{"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled})
	writeData(w, 200, map[string]any{"resourceId": rid.String(), "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled})
}

func (app *App) handleConfigureLabAcceptance(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	labID, err1 := uuid.Parse(req.LaboratoryID)
	tid, err2 := uuid.Parse(req.SampleTypeID)
	if err1 != nil || err2 != nil {
		writeErr(w, 400, "invalid_acceptance", "invalid ids")
		return
	}
	lab, _ := app.Store.GetLocation(r.Context(), labID)
	st, _ := app.Store.GetSampleType(r.Context(), tid)
	if lab == nil || st == nil || !lab.Functions.Laboratory {
		writeErr(w, 400, "invalid_acceptance", "invalid laboratory or type")
		return
	}
	id, err := app.Store.UpsertLabAcceptance(r.Context(), labID, tid, req.Accepts)
	if err != nil {
		writeErr(w, 500, "internal_error", "save")
		return
	}
	_, _ = app.Store.BumpNetworkRevision(r.Context())
	go app.rebuildServiceabilitySnapshot(context.Background())
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "configure_laboratory_acceptance", "laboratory", labID.String(), true, map[string]interface{}{"sampleTypeId": tid.String(), "accepts": req.Accepts})
	writeData(w, 200, map[string]any{"acceptanceId": id.String(), "accepts": req.Accepts})
}

func (app *App) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
