func (app *App) handleSplit(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		SampleIDs           []string `json:"sampleIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	jid, err := uuid.Parse(req.JourneyID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	j, _ := app.Store.GetJourney(r.Context(), jid)
	if j == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if req.ExpectedPlanVersion != j.PlanVersion {
		writeErr(w, 409, "stale_plan", "stale plan")
		return
	}
	j.PlanVersion++
	_ = app.Store.UpdateJourney(r.Context(), *j)
	// create a child journey for split samples (simple clone of remaining)
	child := Journey{
		ID: uuid.New(), ParentJourneyID: &j.ID, PlanVersion: 1, RouteMode: j.RouteMode,
		Status: StatusPlanned, EstimatedDeliveryAt: j.EstimatedDeliveryAt,
		TotalCostUnits: j.TotalCostUnits, CapacityUsed: 1, Valid: true,
	}
	_ = app.Store.InsertJourney(r.Context(), child)
	for _, s := range req.SampleIDs {
		sid, err := uuid.Parse(s)
		if err != nil {
			continue
		}
		_ = app.Store.AddJourneySample(r.Context(), child.ID, sid)
		sm, _ := app.Store.GetSample(r.Context(), sid)
		if sm != nil {
			sm.ActiveJourneyID = &child.ID
			_ = app.Store.UpdateSample(r.Context(), *sm)
		}
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "split_journey", "journey", j.ID.String(), true, map[string]interface{}{"child": child.ID.String()})
	writeData(w, 200, map[string]any{
		"originalJourneyId": j.ID.String(),
		"newJourneyId":      child.ID.String(),
		"planVersion":       j.PlanVersion,
	})
}

func (app *App) handleMerge(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		JourneyIDs          []string `json:"journeyIds"`
		ExpectedPlanVersions []int   `json:"expectedPlanVersions"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if len(req.JourneyIDs) < 2 {
		writeErr(w, 400, "invalid_json", "need at least two journeys")
		return
	}
	var journeys []Journey
	var samples []Sample
	for i, js := range req.JourneyIDs {
		id, err := uuid.Parse(js)
		if err != nil {
			writeErr(w, 404, "not_found", "not found")
			return
		}
		j, _ := app.Store.GetJourney(r.Context(), id)
		if j == nil {
			writeErr(w, 404, "not_found", "not found")
			return
		}
		if i < len(req.ExpectedPlanVersions) && req.ExpectedPlanVersions[i] != j.PlanVersion {
			writeErr(w, 409, "stale_plan", "stale plan")
			return
		}
		journeys = append(journeys, *j)
		sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
		for _, sid := range sids {
			sm, _ := app.Store.GetSample(r.Context(), sid)
			if sm != nil {
				samples = append(samples, *sm)
			}
		}
	}
	// compatibility
	if !compatibleBatch(samples) {
		writeErr(w, 409, "incompatible_batch", "samples cannot travel together")
		return
	}
	primary := journeys[0]
	primary.PlanVersion++
	primary.RouteMode = RouteBatched
	_ = app.Store.UpdateJourney(r.Context(), primary)
	for i := 1; i < len(journeys); i++ {
		sids, _ := app.Store.JourneySampleIDs(r.Context(), journeys[i].ID)
		for _, sid := range sids {
			_ = app.Store.AddJourneySample(r.Context(), primary.ID, sid)
			sm, _ := app.Store.GetSample(r.Context(), sid)
			if sm != nil {
				sm.ActiveJourneyID = &primary.ID
				_ = app.Store.UpdateSample(r.Context(), *sm)
			}
		}
		journeys[i].Status = StatusCancelled
		journeys[i].PlanVersion++
		_ = app.Store.UpdateJourney(r.Context(), journeys[i])
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "merge_journeys", "journey", primary.ID.String(), true, nil)
	writeData(w, 200, map[string]any{"journeyId": primary.ID.String(), "planVersion": primary.PlanVersion, "routeMode": primary.RouteMode})
}

func compatibleBatch(samples []Sample) bool {
	for i, a := range samples {
		stA, _ := (*App)(nil).unused()
		_ = stA
		if false {
			_ = i
		}
		for j, b := range samples {
			if i == j {
				continue
			}
			for _, inc := range a.IncompatibleSampleTypes {
				if inc == b.SampleTypeID {
					return false
				}
			}
			// Pulse must not wait to be batched
			// check names via type id known defaults
			if a.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" ||
				b.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" {
				return false
			}
			// temperature overlap
			if a.TemperatureMaxC < b.TemperatureMinC || b.TemperatureMaxC < a.TemperatureMinC {
				return false
			}
		}
	}
	return true
}

func (*App) unused() (any, error) { return nil, nil }

func (app *App) handleEditPlan(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	jid, err := uuid.Parse(req.JourneyID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	app.replanJourney(w, r, jid, req.ExpectedPlanVersion, "edit")
}

func (app *App) handleDisruption(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.ResourceType == "" || req.ResourceID == "" {
		writeErr(w, 400, "invalid_json", "resource required")
		return
	}
	at := time.Now().UTC()
	if req.OccurredAt != "" {
		t, err := parseTime(req.OccurredAt)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid occurredAt")
			return
		}
		at = t
	}
	// deactivate resource if applicable
	if id, err := uuid.Parse(req.ResourceID); err == nil {
		switch req.ResourceType {
		case "node", "location", "laboratory":
			_ = app.Store.SetLocationActive(r.Context(), id, false)
			_, _ = app.Store.BumpNetworkRevision(r.Context())
			go app.rebuildServiceabilitySnapshot(r.Context())
		case "connection", "route":
			_ = app.Store.SetConnectionActive(r.Context(), id, false)
			_, _ = app.Store.BumpNetworkRevision(r.Context())
			go app.rebuildServiceabilitySnapshot(r.Context())
		case "worker":
			u, _ := app.Store.GetUserByID(r.Context(), id)
			if u != nil {
				_ = app.Store.SetWorkerAvailability(r.Context(), id, false, u.CapacityUnits)
			}
		}
	}
	affected := app.findAffectedJourneys(r.Context(), req.ResourceType, req.ResourceID)
	var results []map[string]any
	for _, j := range affected {
		// replan each
		sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
		if len(sids) == 0 {
			continue
		}
		sm, _ := app.Store.GetSample(r.Context(), sids[0])
		if sm == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled {
			continue
		}
		holder := sm.CurrentHolderID
		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
		origin := Coordinate{Latitude: sm.OriginLat, Longitude: sm.OriginLng}
		if sm.LatestLat != nil {
			origin = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
		}
		res, _ := app.computeServiceability(r.Context(), origin, OriginNode, sm.OriginNodeID, sm.SampleTypeID, time.Now().UTC(), sm.DeliveryDeadline, sm.EarliestCollectionAt, sm.LatestCollectionAt, st != nil && st.RequiresCooledRoute)
		j.PlanVersion++
		if !res.Serviceable {
			sm.Status = StatusExpired
			sm.CurrentHolderID = holder
			_ = app.Store.UpdateSample(r.Context(), *sm)
			rs := "expired"
			j.ReplanStatus = &rs
			j.Valid = false
			_ = app.Store.UpdateJourney(r.Context(), j)
			results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "expired"})
			continue
		}
		asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
		for _, a := range asgs {
			if a.Status != StatusCompleted {
				a.Status = StatusCancelled
				a.OfferedTo = nil
				_ = app.Store.UpdateAssignment(r.Context(), a)
			}
		}
		rs := "replanned"
		j.ReplanStatus = &rs
		j.Valid = true
		_ = app.Store.UpdateJourney(r.Context(), j)
		sm.CurrentHolderID = holder
		_ = app.Store.UpdateSample(r.Context(), *sm)
		results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "replanned", "planVersion": j.PlanVersion})
	}
	if results == nil {
		results = []map[string]any{}
	}
	_ = at
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
	writeData(w, 200, map[string]any{"affected": results})
}

func (app *App) findAffectedJourneys(ctx context.Context, resourceType, resourceID string) []Journey {
	samples, _ := app.Store.ListSamples(ctx)
	seen := map[uuid.UUID]bool{}
	var out []Journey
	rid, _ := uuid.Parse(resourceID)
	for _, sm := range samples {
		if sm.ActiveJourneyID == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired {
			continue
		}
		if seen[*sm.ActiveJourneyID] {
			continue
		}
		hit := false
		if resourceType == "worker" && sm.CurrentHolderID != nil && sm.CurrentHolderID.String() == resourceID {
			hit = true
		}
		if (resourceType == "laboratory" || resourceType == "node" || resourceType == "location") && sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID == rid {
			hit = true
		}
		asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
		for _, a := range asgs {
			if a.Status == StatusCompleted {
				continue
			}
			if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
				hit = true
			}
			if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
				((a.NodeID != nil && *a.NodeID == rid) || (a.LaboratoryID != nil && *a.LaboratoryID == rid) ||
					(a.FromLocationID != nil && *a.FromLocationID == rid) || (a.ToLocationID != nil && *a.ToLocationID == rid)) {
				hit = true
			}
		}
		if hit {
			j, _ := app.Store.GetJourney(ctx, *sm.ActiveJourneyID)
			if j != nil {
				seen[j.ID] = true
				out = append(out, *j)
			}
		}
	}
	sort.Slice(out, func(i, k int) bool { return out[i].ID.String() < out[k].ID.String() })
	return out
}

