	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "decline_assignment", "assignment", a.ID.String(), true, nil)
	writeData(w, 200, map[string]any{"assignmentId": a.ID.String(), "status": "declined"})
}

func (app *App) handleCollectSeal(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleCollectionProfessional, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID     string     `json:"assignmentId"`
		CollectedAt      string     `json:"collectedAt"`
		Sealed           bool       `json:"sealed"`
		ObservedLocation Coordinate `json:"observedLocation"`
		IdempotencyKey   string     `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !req.Sealed {
		writeErr(w, 400, "invalid_json", "sealed must be true")
		return
	}
	if !validCoord(req.ObservedLocation) {
		writeErr(w, 400, "invalid_coordinate", "invalid location")
		return
	}
	at, err := parseTime(req.CollectedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid collectedAt")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if a.Kind != KindCollection {
		writeErr(w, 409, "invalid_state", "not a collection assignment")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	if a.Status != StatusAccepted && a.Status != StatusInProgress {
		writeErr(w, 409, "invalid_state", "assignment not accepted")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if at.Before(sm.EarliestCollectionAt) || at.After(sm.LatestCollectionAt) {
		writeErr(w, 409, "outside_collection_window", "outside collection window")
		return
	}
	now := time.Now().UTC()
	a.Status = StatusCompleted
	a.CompletedAt = &now
	_ = app.Store.UpdateAssignment(r.Context(), *a)
	sm.Sealed = true
	sm.SealedAt = &at
	sm.Status = StatusSealed
	sm.CurrentHolderID = &auth.User.ID
	sm.LatestLat = &req.ObservedLocation.Latitude
	sm.LatestLng = &req.ObservedLocation.Longitude
	sm.LocationRecordedAt = &at
	_ = app.Store.UpdateSample(r.Context(), *sm)
	st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
	all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
	_ = app.offerNext(r.Context(), sm, all, st)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "collect_and_seal", "sample", sm.ID.String(), true, nil)
	_, _ = app.Store.AddRealtime(r.Context(), "sample.sealed", "sample", sm.ID.String(), nil)
	writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "sealed": true, "status": sm.Status})
}

func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	fromID, err1 := uuid.Parse(req.FromAssignmentID)
	toID, err2 := uuid.Parse(req.ToAssignmentID)
	if err1 != nil || err2 != nil {
		writeErr(w, 400, "invalid_json", "invalid assignment")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != auth.User.ID {
		writeErr(w, 409, "not_current_holder", "not current holder")
		return
	}
	from, _ := app.Store.GetAssignment(r.Context(), fromID)
	to, _ := app.Store.GetAssignment(r.Context(), toID)
	if from == nil || to == nil || from.SampleID != sid || to.SampleID != sid {
		writeErr(w, 409, "invalid_handoff_pair", "invalid pair")
		return
	}
	if from.WorkerID == nil || *from.WorkerID != auth.User.ID {
		writeErr(w, 409, "invalid_handoff_pair", "sender not on from assignment")
		return
	}
	if to.WorkerID == nil {
		writeErr(w, 409, "invalid_handoff_pair", "receiver not accepted")
		return
	}
	if from.Sequence >= to.Sequence {
		writeErr(w, 409, "invalid_handoff_pair", "not sequential")
		return
	}
	if sm.PendingHandoffID != nil {
		// idempotent-ish: return existing
		h, _ := app.Store.GetHandoff(r.Context(), *sm.PendingHandoffID)
		if h != nil && h.FromAssignmentID == fromID && h.ToAssignmentID == toID {
			writeData(w, 201, handoffPayload(*h))
			return
		}
		writeErr(w, 409, "handoff_already_pending", "already pending")
		return
	}
	now := time.Now().UTC()
	h := Handoff{
		ID: uuid.New(), SampleID: sid, FromAssignmentID: fromID, ToAssignmentID: toID,
		SenderID: auth.User.ID, ReceiverID: *to.WorkerID, Status: "pending",
		SenderConfirmed: false, ReceiverConfirmed: false, InitiatedAt: now,
	}
	if err := app.Store.InsertHandoff(r.Context(), h); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	sm.PendingHandoffID = &h.ID
	_ = app.Store.UpdateSample(r.Context(), *sm)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "initiate_handoff", "sample", sid.String(), true, map[string]interface{}{"handoffId": h.ID.String()})
	writeData(w, 201, handoffPayload(h))
}

func handoffPayload(h Handoff) map[string]any {
	return map[string]any{
		"handoffId":         h.ID.String(),
		"sampleId":          h.SampleID.String(),
		"fromAssignmentId":  h.FromAssignmentID.String(),
		"toAssignmentId":    h.ToAssignmentID.String(),
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
	}
}

func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		HandoffID      string `json:"handoffId"`
		Party          string `json:"party"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Party != "sender" && req.Party != "receiver" {
		writeErr(w, 400, "invalid_json", "invalid party")
		return
	}
	hid, err := uuid.Parse(req.HandoffID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	h, _ := app.Store.GetHandoff(r.Context(), hid)
	if h == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if h.Status == "confirmed" {
		writeData(w, 200, handoffPayload(*h))
		return
	}
	if req.Party == "sender" {
		if h.SenderID != auth.User.ID {
			writeErr(w, 403, "forbidden", "not sender")
			return
		}
		h.SenderConfirmed = true
	} else {
		if h.ReceiverID != auth.User.ID {
			writeErr(w, 403, "forbidden", "not receiver")
			return
		}
		h.ReceiverConfirmed = true
	}
	if h.SenderConfirmed && h.ReceiverConfirmed {
		now := time.Now().UTC()
		h.Status = "confirmed"
		h.ConfirmedAt = &now
		sm, _ := app.Store.GetSample(r.Context(), h.SampleID)
		if sm != nil {
			sm.CurrentHolderID = &h.ReceiverID
			sm.PendingHandoffID = nil
			from, _ := app.Store.GetAssignment(r.Context(), h.FromAssignmentID)
			to, _ := app.Store.GetAssignment(r.Context(), h.ToAssignmentID)
			if from != nil && from.Status != StatusCompleted {
				from.Status = StatusCompleted
				from.CompletedAt = &now
				_ = app.Store.UpdateAssignment(r.Context(), *from)
			}
			if to != nil && to.Status == StatusAccepted {
				to.Status = StatusInProgress
				_ = app.Store.UpdateAssignment(r.Context(), *to)
			}
			if to != nil {
				switch to.Kind {
				case KindTransport:
					sm.Status = StatusInTransit
				case KindNode:
					sm.Status = StatusAtNode
				case KindLaboratory:
					sm.Status = StatusAtLaboratory
				}
			}
			_ = app.Store.UpdateSample(r.Context(), *sm)
			st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
			all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
			_ = app.offerNext(r.Context(), sm, all, st)
		}
	}
	_ = app.Store.UpdateHandoff(r.Context(), *h)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "confirm_handoff", "handoff", h.ID.String(), true, map[string]interface{}{"party": req.Party, "status": h.Status})
	writeData(w, 200, handoffPayload(*h))
}

func (app *App) handleConfirmReceipt(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleLaboratoryTeam, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	lid, err := uuid.Parse(req.LaboratoryID)
	if err != nil {
		writeErr(w, 400, "invalid_json", "invalid laboratory")
		return
	}
	at, err := parseTime(req.ReceivedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid receivedAt")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if sm.Status == StatusReceived {
		writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status})
		return
	}
	if at.After(sm.DeliveryDeadline) {
		// still receive but mark expired? Spec: if received after deadline it's still received; expired is if no valid route
	}
	sm.Status = StatusReceived
	sm.ReceivedLaboratoryID = &lid
	sm.ReceivedAt = &at
	sm.CurrentHolderID = &auth.User.ID
	sm.LocationRecordedAt = &at
	_ = app.Store.UpdateSample(r.Context(), *sm)
	_ = app.Store.ReleaseReservationsForSample(r.Context(), sm.ID)
	if sm.ActiveJourneyID != nil {
		j, _ := app.Store.GetJourney(r.Context(), *sm.ActiveJourneyID)
		if j != nil {
			j.Status = StatusCompleted
			_ = app.Store.UpdateJourney(r.Context(), *j)
		}
	}
	asgs, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
	now := time.Now().UTC()
	for _, a := range asgs {
		if a.Kind == KindLaboratory && (a.Status == StatusAccepted || a.Status == StatusInProgress || a.Status == StatusPending) {
			a.Status = StatusCompleted
			a.CompletedAt = &now
			if a.WorkerID == nil {
				a.WorkerID = &auth.User.ID
			}
			_ = app.Store.UpdateAssignment(r.Context(), a)
		}
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "confirm_laboratory_receipt", "sample", sm.ID.String(), true, nil)
	_, _ = app.Store.AddRealtime(r.Context(), "sample.received", "sample", sm.ID.String(), nil)
	writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status})
}

func (app *App) handleLabException(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleLaboratoryTeam, RoleAdministrator, RoleDispatcher) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		Reason         string `json:"reason"`
		Notes          string `json:"notes"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Reason == "" {
		writeErr(w, 400, "invalid_json", "reason required")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	sm.Status = StatusException
	sm.Exception = map[string]interface{}{"reason": req.Reason, "notes": req.Notes}
	_ = app.Store.UpdateSample(r.Context(), *sm)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "laboratory_exception", "sample", sm.ID.String(), true, sm.Exception)
	writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status, "exception": sm.Exception})
}

func (app *App) handleCheckpoint(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		SampleID               string  `json:"sampleId"`
		AssignmentID           string  `json:"assignmentId"`
		LocationID             *string `json:"locationId"`
		ContainerType          string  `json:"containerType"`
		ObservedTemperatureC   float64 `json:"observedTemperatureC"`
		RecordedAt             string  `json:"recordedAt"`
		IdempotencyKey         string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.ContainerType == "" {
		writeErr(w, 400, "invalid_json", "container required")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != auth.User.ID {
		writeErr(w, 409, "not_current_holder", "not current holder")
		return
	}
	var locID *uuid.UUID
	if req.LocationID != nil && *req.LocationID != "" {
		id, err := uuid.Parse(*req.LocationID)
		if err != nil {
			writeErr(w, 400, "invalid_json", "invalid location")
			return
		}
		locID = &id
	}
	compliant := req.ContainerType == sm.ContainerType &&
		req.ObservedTemperatureC >= sm.TemperatureMinC &&
		req.ObservedTemperatureC <= sm.TemperatureMaxC
	cid := uuid.New()
	if err := app.Store.InsertCheckpoint(r.Context(), cid, sid, aid, locID, req.ContainerType, req.ObservedTemperatureC, at, compliant); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	if !compliant {
		sm.Status = StatusException
		sm.Exception = map[string]interface{}{
			"reason":                 "handling_checkpoint_violation",
			"containerType":          req.ContainerType,
			"observedTemperatureC":   req.ObservedTemperatureC,
		}
		_ = app.Store.UpdateSample(r.Context(), *sm)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "handling_checkpoint", "sample", sid.String(), true, map[string]interface{}{"compliant": compliant})
	out := map[string]any{"checkpointId": cid.String(), "compliant": compliant}
	if !compliant {
		out["exception"] = sm.Exception
	}
	writeData(w, 201, out)
}

func (app *App) handleRecordLocation(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		RecordedAt   string     `json:"recordedAt"`
		Sequence     int        `json:"sequence"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.Sequence < 1 {
		writeErr(w, 400, "invalid_json", "sequence must be >= 1")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "assignment")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	last, err := app.Store.LastWorkerLocSeq(r.Context(), aid)
	if err != nil {
		writeErr(w, 500, "internal_error", "seq")
		return
	}
	if req.Sequence <= last {
		writeErr(w, 409, "stale_location", "sequence not increasing")
		return
	}
	if err := app.Store.InsertWorkerLocation(r.Context(), auth.User.ID, aid, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, at); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm != nil && sm.CurrentHolderID != nil && *sm.CurrentHolderID == auth.User.ID {
		sm.LatestLat = &req.Coordinate.Latitude
		sm.LatestLng = &req.Coordinate.Longitude
		sm.LocationRecordedAt = &at
		_ = app.Store.UpdateSample(r.Context(), *sm)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "record_location", "assignment", aid.String(), true, nil)
	writeData(w, 200, map[string]any{"assignmentId": aid.String(), "sequence": req.Sequence})
}

func (app *App) handleProgress(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		Note           string `json:"note"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Status != StatusInProgress && req.Status != StatusCompleted {
		writeErr(w, 400, "invalid_json", "invalid status")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	now := time.Now().UTC()
	a.Status = req.Status
	if req.Status == StatusCompleted {
		a.CompletedAt = &now
	}
	_ = app.Store.UpdateAssignment(r.Context(), *a)
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm != nil && req.Status == StatusInProgress {
		if a.Kind == KindTransport {
			sm.Status = StatusInTransit
		} else if a.Kind == KindCollection {
			sm.Status = StatusCollecting
		}
		_ = app.Store.UpdateSample(r.Context(), *sm)
	}
	if sm != nil && req.Status == StatusCompleted {
		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
		all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
		_ = app.offerNext(r.Context(), sm, all, st)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "update_progress", "assignment", a.ID.String(), true, map[string]interface{}{"status": req.Status, "note": req.Note})
	writeData(w, 200, map[string]any{"assignmentId": a.ID.String(), "status": a.Status})
}

func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	_ = json.NewDecoder(r.Body).Decode(&req)
	role := auth.ActiveRole
	if req.Role != "" {
		if req.Role != auth.ActiveRole {
			writeErr(w, 403, "forbidden", "role must match active role")
			return
		}
		role = req.Role
	}
	now := time.Now().UTC()
	var pending, inProg, completed []map[string]any

	switch role {
	case RoleRequester:
		samples, _ := app.Store.ListSamplesByRequester(r.Context(), auth.User.ID)
		for _, sm := range samples {
			item := app.sampleWorkItem(r.Context(), sm, now)
			switch {
			case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
				completed = append(completed, item)
			case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
	case RoleAdministrator, RoleDispatcher:
		samples, _ := app.Store.ListSamples(r.Context())
		for _, sm := range samples {
			item := app.sampleWorkItem(r.Context(), sm, now)
			switch {
			case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
				completed = append(completed, item)
			case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
	default:
		asgs, _ := app.Store.ListAssignmentsForWorker(r.Context(), auth.User.ID)
		for _, a := range asgs {
			// filter by role kind
			if !assignmentMatchesRole(a.Kind, role) {
				continue
			}
			item := app.assignmentWorkItem(r.Context(), a)
			switch a.Status {
			case StatusCompleted, StatusCancelled:
				completed = append(completed, item)
			case StatusAccepted, StatusInProgress:
				inProg = append(inProg, item)
			default:
				pending = append(pending, item)
			}
		}
	}
	if pending == nil {
		pending = []map[string]any{}
	}
	if inProg == nil {
		inProg = []map[string]any{}
	}
	if completed == nil {
		completed = []map[string]any{}
	}
	writeData(w, 200, map[string]any{
		"role":              role,
		"pending":           pending,
		"inProgress":        inProg,
		"completed":         completed,
		"current":           append(append([]map[string]any{}, pending...), inProg...),
		"past":              completed,
	})
}

func assignmentMatchesRole(kind, role string) bool {
	switch role {
	case RoleCollectionProfessional:
		return kind == KindCollection
	case RoleDeliveryPartner:
		return kind == KindTransport
	case RoleNodeHandler:
		return kind == KindNode
	case RoleLaboratoryTeam:
		return kind == KindLaboratory
	}
	return true
}

