:root {
  color-scheme: light;
  --bg: #f4f1ea;
  --paper: #fffdf8;
  --ink: #1d2a24;
  --muted: #5c6b64;
  --line: #d7cfc2;
  --accent: #0f6b57;
  --accent-2: #c45c26;
  --danger: #9b2c2c;
  --ok: #1f7a4d;
  --warn: #9a6700;
  font-family: "IBM Plex Sans", "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html, body, #root { margin: 0; min-height: 100%; }
body { background: var(--bg); color: var(--ink); }

a { color: inherit; }

.app-shell { min-height: 100vh; display: flex; flex-direction: column; }
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 12px 20px; background: #16352d; color: #f7f3ea;
}
.brand { font-weight: 700; letter-spacing: 0.02em; }
.topbar-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.nav {
  display: flex; gap: 8px; padding: 10px 20px; background: var(--paper); border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.nav a, .nav button.linkish {
  text-decoration: none; border: 1px solid var(--line); background: white; padding: 6px 10px;
  border-radius: 999px; font-size: 14px; cursor: pointer;
}
.nav a.active { background: var(--accent); color: white; border-color: var(--accent); }
.page { padding: 20px; max-width: 1280px; width: 100%; margin: 0 auto; }
.grid { display: grid; gap: 16px; }
.grid.two { grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }
.card {
  background: var(--paper); border: 1px solid var(--line); border-radius: 16px; padding: 16px;
  box-shadow: 0 8px 24px rgba(29,42,36,0.04);
}
h1, h2, h3 { margin: 0 0 10px; }
label { display: block; font-size: 13px; color: var(--muted); margin: 10px 0 4px; }
input, select, textarea, button {
  font: inherit;
}
input, select, textarea {
  width: 100%; padding: 8px 10px; border: 1px solid var(--line); border-radius: 10px; background: white;
}
textarea { min-height: 80px; }
button {
  border: 0; background: var(--accent); color: white; padding: 8px 12px; border-radius: 10px; cursor: pointer;
}
button.secondary { background: #35564d; }
button.danger { background: var(--danger); }
button.ghost { background: transparent; color: inherit; border: 1px solid currentColor; }
.banner { padding: 10px 12px; border-radius: 10px; margin: 10px 0; }
.banner.error { background: #fde8e8; color: var(--danger); }
.banner.ok { background: #e7f6ee; color: var(--ok); }
.banner.warn { background: #fff4d6; color: var(--warn); }
.login {
  min-height: 100vh; display: grid; place-items: center; padding: 24px;
  background: radial-gradient(circle at top left, #2c6a59, #12261f 55%);
}
.login-card { width: min(420px, 100%); }
.muted { color: var(--muted); font-size: 13px; }
.list { display: grid; gap: 10px; }
.item {
  border: 1px solid var(--line); border-radius: 12px; padding: 12px; background: white;
}
.row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.tag { display: inline-block; padding: 2px 8px; border-radius: 999px; background: #e8efe9; font-size: 12px; }
.tag.exception { background: #fde8e8; color: var(--danger); }
.tag.stale { background: #fff4d6; color: var(--warn); }
.timeline { border-left: 2px solid var(--line); margin-left: 8px; padding-left: 12px; }
.timeline li { margin: 0 0 10px; list-style: none; }
.map-wrap { height: 420px; border-radius: 16px; overflow: hidden; border: 1px solid var(--line); }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { text-align: left; padding: 8px; border-bottom: 1px solid var(--line); vertical-align: top; }
.hidden { display: none; }

