    mustNotBatch?: boolean;
  }>;
  locations: Array<{
    locationId: string;
    name: string;
    kind: string;
    latitude: number;
    longitude: number;
    active: boolean;
    functions?: string[];
  }>;
  map: { styleUrl: string };
};

