  assignmentId?: string;
  requestId?: string;
  sampleId?: string;
  journeyId?: string;
  status?: string;
  kind?: string;
  title?: string;
  summary?: string;
  current?: boolean;
  completed?: boolean;
  offeredToUserId?: string;
  sampleTypeName?: string;
  exception?: boolean;
};

export type SampleState = {
  sampleId: string;
  requestId?: string;
  status?: string;
  currentHolderUserId?: string;
  currentHolderName?: string;
  currentLocationId?: string;
  currentLocationName?: string;
  lastKnownLatitude?: number;
  lastKnownLongitude?: number;
  lastLocationAt?: string;
  locationStale?: boolean;
  stale?: boolean;
  exception?: boolean;
  exceptionReason?: string;
  routeProgress?: string;
  timeline?: Array<{ at: string; status: string; note?: string }>;
  statusHistory?: Array<{ at: string; status: string; note?: string }>;
};

export type OperationsState = {
  samples: any[];
  workers: any[];
  locations: any[];
  routes: any[];
  exceptions: any[];
  nodes?: any[];
  laboratories?: any[];
};

