   117	func (app *App) handleCollectSeal(w http.ResponseWriter, r *http.Request) {
   118		auth := getAuth(r)
   119		if !roleSelected(auth) {
   120			writeErr(w, 409, "role_not_selected", "select a role")
   121			return
   122		}
   123		if !requireRole(auth, RoleCollectionProfessional, RoleAdministrator) {
   124			writeErr(w, 403, "forbidden", "forbidden")
   125			return
   126		}
   127		var req struct {
   128			AssignmentID     string     `json:"assignmentId"`
   129			CollectedAt      string     `json:"collectedAt"`
   130			Sealed           bool       `json:"sealed"`
   131			ObservedLocation Coordinate `json:"observedLocation"`
   132			IdempotencyKey   string     `json:"idempotencyKey"`
   133		}
   134		if err := decodeJSON(r, &req); err != nil {
   135			writeErr(w, 400, "invalid_json", "invalid json")
   136			return
   137		}
   138		if !req.Sealed {
   139			writeErr(w, 400, "invalid_json", "sealed must be true")
   140			return
   141		}
   142		if !validCoord(req.ObservedLocation) {
   143			writeErr(w, 400, "invalid_coordinate", "invalid location")
   144			return
   145		}
   146		at, err := parseTime(req.CollectedAt)
   147		if err != nil {
   148			writeErr(w, 400, "invalid_time", "invalid collectedAt")
   149			return
   150		}
   151		aid, err := uuid.Parse(req.AssignmentID)
   152		if err != nil {
   153			writeErr(w, 404, "not_found", "not found")
   154			return
   155		}
   156		a, _ := app.Store.GetAssignment(r.Context(), aid)
   157		if a == nil {
   158			writeErr(w, 404, "not_found", "not found")
   159			return
   160		}
   161		if a.Kind != KindCollection {
   162			writeErr(w, 409, "invalid_state", "not a collection assignment")
   163			return
   164		}
   165		if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
   166			writeErr(w, 403, "forbidden", "not your assignment")
   167			return
   168		}
   169		if a.Status != StatusAccepted && a.Status != StatusInProgress {
   170			writeErr(w, 409, "invalid_state", "assignment not accepted")
   171			return
   172		}
   173		sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
   174		if sm == nil {
   175			writeErr(w, 404, "not_found", "sample")
   176			return
   177		}
   178		if at.Before(sm.EarliestCollectionAt) || at.After(sm.LatestCollectionAt) {
   179			writeErr(w, 409, "outside_collection_window", "outside collection window")
   180			return
   181		}
   182		now := time.Now().UTC()
   183		a.Status = StatusCompleted
   184		a.CompletedAt = &now
   185		_ = app.Store.UpdateAssignment(r.Context(), *a)
   186		sm.Sealed = true
   187		sm.SealedAt = &at
   188		sm.Status = StatusSealed
   189		sm.CurrentHolderID = &auth.User.ID
   190		sm.LatestLat = &req.ObservedLocation.Latitude
   191		sm.LatestLng = &req.ObservedLocation.Longitude
   192		sm.LocationRecordedAt = &at
   193		_ = app.Store.UpdateSample(r.Context(), *sm)
   194		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
   195		all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
