  1704	func compatibleBatch(samples []Sample) bool {
  1705		for i, a := range samples {
  1706			stA, _ := (*App)(nil).unused()
  1707			_ = stA
  1708			if false {
  1709				_ = i
  1710			}
  1711			for j, b := range samples {
  1712				if i == j {
  1713					continue
  1714				}
  1715				for _, inc := range a.IncompatibleSampleTypes {
  1716					if inc == b.SampleTypeID {
  1717						return false
  1718					}
  1719				}
  1720				// Pulse must not wait to be batched
  1721				// check names via type id known defaults
  1722				if a.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" ||
  1723					b.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" {
  1724					return false
  1725				}
  1726				// temperature overlap
  1727				if a.TemperatureMaxC < b.TemperatureMinC || b.TemperatureMaxC < a.TemperatureMinC {
  1728					return false
  1729				}
  1730			}
  1731		}
  1732		return true
  1733	}
