  1764	func (app *App) handleDisruption(w http.ResponseWriter, r *http.Request) {
  1765		auth := getAuth(r)
  1766		if !roleSelected(auth) {
  1767			writeErr(w, 409, "role_not_selected", "select a role")
  1768			return
  1769		}
  1770		if !adminOrDispatcher(auth) {
  1771			writeErr(w, 403, "forbidden", "forbidden")
  1772			return
  1773		}
  1774		var req struct {
  1775			ResourceType   string `json:"resourceType"`
  1776			ResourceID     string `json:"resourceId"`
  1777			Reason         string `json:"reason"`
  1778			OccurredAt     string `json:"occurredAt"`
  1779			IdempotencyKey string `json:"idempotencyKey"`
  1780		}
  1781		if err := decodeJSON(r, &req); err != nil {
  1782			writeErr(w, 400, "invalid_json", "invalid json")
  1783			return
  1784		}
  1785		if req.ResourceType == "" || req.ResourceID == "" {
  1786			writeErr(w, 400, "invalid_json", "resource required")
  1787			return
  1788		}
  1789		at := time.Now().UTC()
  1790		if req.OccurredAt != "" {
  1791			t, err := parseTime(req.OccurredAt)
  1792			if err != nil {
  1793				writeErr(w, 400, "invalid_time", "invalid occurredAt")
  1794				return
  1795			}
  1796			at = t
  1797		}
  1798		// deactivate resource if applicable
  1799		if id, err := uuid.Parse(req.ResourceID); err == nil {
  1800			switch req.ResourceType {
  1801			case "node", "location", "laboratory":
  1802				_ = app.Store.SetLocationActive(r.Context(), id, false)
  1803				_, _ = app.Store.BumpNetworkRevision(r.Context())
  1804				go app.rebuildServiceabilitySnapshot(r.Context())
  1805			case "connection", "route":
  1806				_ = app.Store.SetConnectionActive(r.Context(), id, false)
  1807				_, _ = app.Store.BumpNetworkRevision(r.Context())
  1808				go app.rebuildServiceabilitySnapshot(r.Context())
  1809			case "worker":
  1810				u, _ := app.Store.GetUserByID(r.Context(), id)
  1811				if u != nil {
  1812					_ = app.Store.SetWorkerAvailability(r.Context(), id, false, u.CapacityUnits)
  1813				}
  1814			}
  1815		}
  1816		affected := app.findAffectedJourneys(r.Context(), req.ResourceType, req.ResourceID)
  1817		var results []map[string]any
  1818		for _, j := range affected {
  1819			// replan each
  1820			sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
  1821			if len(sids) == 0 {
  1822				continue
  1823			}
  1824			sm, _ := app.Store.GetSample(r.Context(), sids[0])
  1825			if sm == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled {
  1826				continue
  1827			}
  1828			holder := sm.CurrentHolderID
  1829			st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
  1830			origin := Coordinate{Latitude: sm.OriginLat, Longitude: sm.OriginLng}
  1831			if sm.LatestLat != nil {
  1832				origin = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
  1833			}
  1834			res, _ := app.computeServiceability(r.Context(), origin, OriginNode, sm.OriginNodeID, sm.SampleTypeID, time.Now().UTC(), sm.DeliveryDeadline, sm.EarliestCollectionAt, sm.LatestCollectionAt, st != nil && st.RequiresCooledRoute)
  1835			j.PlanVersion++
  1836			if !res.Serviceable {
  1837				sm.Status = StatusExpired
  1838				sm.CurrentHolderID = holder
  1839				_ = app.Store.UpdateSample(r.Context(), *sm)
  1840				rs := "expired"
  1841				j.ReplanStatus = &rs
  1842				j.Valid = false
  1843				_ = app.Store.UpdateJourney(r.Context(), j)
  1844				results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "expired"})
  1845				continue
  1846			}
  1847			asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
  1848			for _, a := range asgs {
  1849				if a.Status != StatusCompleted {
  1850					a.Status = StatusCancelled
  1851					a.OfferedTo = nil
  1852					_ = app.Store.UpdateAssignment(r.Context(), a)
  1853				}
  1854			}
  1855			rs := "replanned"
  1856			j.ReplanStatus = &rs
  1857			j.Valid = true
  1858			_ = app.Store.UpdateJourney(r.Context(), j)
  1859			sm.CurrentHolderID = holder
  1860			_ = app.Store.UpdateSample(r.Context(), *sm)
  1861			results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "replanned", "planVersion": j.PlanVersion})
  1862		}
  1863		if results == nil {
  1864			results = []map[string]any{}
  1865		}
  1866		_ = at
  1867		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
  1868		writeData(w, 200, map[string]any{"affected": results})
  1869	}
