  1845				continue
  1846			}
  1847			asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
  1848			for _, a := range asgs {
  1849				if a.Status != StatusCompleted {
  1850					a.Status = StatusCancelled
  1851					a.OfferedTo = nil
  1852					_ = app.Store.UpdateAssignment(r.Context(), a)
  1853				}
  1854			}
  1855			rs := "replanned"
  1856			j.ReplanStatus = &rs
