  1871	func (app *App) findAffectedJourneys(ctx context.Context, resourceType, resourceID string) []Journey {
  1872		samples, _ := app.Store.ListSamples(ctx)
  1873		seen := map[uuid.UUID]bool{}
  1874		var out []Journey
  1875		rid, _ := uuid.Parse(resourceID)
  1876		for _, sm := range samples {
  1877			if sm.ActiveJourneyID == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired {
  1878				continue
  1879			}
  1880			if seen[*sm.ActiveJourneyID] {
  1881				continue
  1882			}
  1883			hit := false
  1884			if resourceType == "worker" && sm.CurrentHolderID != nil && sm.CurrentHolderID.String() == resourceID {
  1885				hit = true
  1886			}
  1887			if (resourceType == "laboratory" || resourceType == "node" || resourceType == "location") && sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID == rid {
  1888				hit = true
  1889			}
  1890			asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
  1891			for _, a := range asgs {
  1892				if a.Status == StatusCompleted {
  1893					continue
  1894				}
  1895				if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
  1896					hit = true
  1897				}
  1898				if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
  1899					((a.NodeID != nil && *a.NodeID == rid) || (a.LaboratoryID != nil && *a.LaboratoryID == rid) ||
  1900						(a.FromLocationID != nil && *a.FromLocationID == rid) || (a.ToLocationID != nil && *a.ToLocationID == rid)) {
  1901					hit = true
  1902				}
  1903			}
  1904			if hit {
  1905				j, _ := app.Store.GetJourney(ctx, *sm.ActiveJourneyID)
  1906				if j != nil {
  1907					seen[j.ID] = true
  1908					out = append(out, *j)
  1909				}
  1910			}
  1911		}
  1912		sort.Slice(out, func(i, k int) bool { return out[i].ID.String() < out[k].ID.String() })
