   409		}
   410		at, err := parseTime(req.ReceivedAt)
   411		if err != nil {
   412			writeErr(w, 400, "invalid_time", "invalid receivedAt")
   413			return
   414		}
   415		sm, _ := app.Store.GetSample(r.Context(), sid)
   416		if sm == nil {
   417			writeErr(w, 404, "not_found", "sample")
