    23	  const text = await res.text();
    24	  let body: any = {};
    25	  try {
    26	    body = text ? JSON.parse(text) : {};
    27	  } catch {
    28	    body = { raw: text };
    29	  }
    30	  if (!res.ok) {
    31	    const err = body?.error ?? { code: "http_error", message: text || res.statusText };
    32	    throw Object.assign(new Error(err.message || "request failed"), { status: res.status, body });
