   295		}
   296		if !requireRole(auth, RoleAdministrator) {
   297			writeErr(w, 403, "forbidden", "forbidden")
   298			return
   299		}
   300		var req struct {
   301			Name                       string   `json:"name"`
   302			QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
   303			RequiredQualification      string   `json:"requiredQualification"`
   304			ContainerType              string   `json:"containerType"`
   305			TemperatureMinC            float64  `json:"temperatureMinC"`
   306			TemperatureMaxC            float64  `json:"temperatureMaxC"`
   307			IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
   308			RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
   309			BatchingAllowed            *bool    `json:"batchingAllowed"`
   310		}
   311		if err := decodeJSON(r, &req); err != nil {
   312			writeErr(w, 400, "invalid_json", "invalid json")
   313			return
   314		}
   315		if req.Name == "" || req.ContainerType == "" {
   316			writeErr(w, 400, "invalid_handling_rule", "invalid handling rule")
   317			return
   318		}
   319		if req.TemperatureMinC > req.TemperatureMaxC {
   320			writeErr(w, 400, "invalid_handling_rule", "invalid temperature range")
   321			return
   322		}
   323		qcr := true
   324		if req.QualifiedCollectorRequired != nil {
   325			qcr = *req.QualifiedCollectorRequired
   326		}
   327		cooled := false
   328		if req.RequiresCooledRoute != nil {
   329			cooled = *req.RequiresCooledRoute
   330		}
   331		batch := true
   332		if req.BatchingAllowed != nil {
   333			batch = *req.BatchingAllowed
   334		}
   335		rq := req.RequiredQualification
   336		if rq == "" {
   337			rq = req.Name
   338		}
   339		var incomp []uuid.UUID
   340		for _, s := range req.IncompatibleSampleTypes {
   341			id, err := uuid.Parse(s)
   342			if err != nil {
   343				writeErr(w, 400, "invalid_handling_rule", "invalid incompatible type")
   344				return
   345			}
   346			incomp = append(incomp, id)
   347		}
   348		if incomp == nil {
   349			incomp = []uuid.UUID{}
   350		}
   351		st := SampleType{
   352			ID: uuid.New(), Name: req.Name, QualifiedCollectorRequired: qcr, RequiredQualification: rq,
   353			ContainerType: req.ContainerType, TemperatureMinC: req.TemperatureMinC, TemperatureMaxC: req.TemperatureMaxC,
   354			IncompatibleSampleTypes: incomp, RequiresCooledRoute: cooled, BatchingAllowed: batch,
   355		}
   356		if err := app.Store.InsertSampleType(r.Context(), st); err != nil {
   357			writeErr(w, 500, "internal_error", "insert")
   358			return
   359		}
   360		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_sample_type", "sample_type", st.ID.String(), true, map[string]interface{}{"name": st.Name})
   361		writeData(w, 201, sampleTypePayload(st))
   362	}
