   311		return &PlannedRoute{CollectionPoint: src, Laboratory: dst, Hops: hops, Nodes: nodes, TotalMinutes: totalM, TotalCost: totalC}
   312	}
   313	
   314	func (app *App) materializeJourney(ctx context.Context, sm *Sample, st *SampleType, res ServiceabilityResult, presealed bool, actorID, role string) (*Journey, []Assignment, error) {
   315		if res.Route == nil {
   316			return nil, nil, fmt.Errorf("no route")
   317		}
   318		route := res.Route
   319		now := time.Now().UTC()
   320		jid := uuid.New()
   321		mode := RouteDirect
   322		if len(route.Hops) > 1 {
   323			mode = RouteMultiStop
   324		}
   325		j := Journey{
   326			ID:                  jid,
   327			PlanVersion:         1,
   328			RouteMode:           mode,
   329			Status:              StatusPlanned,
   330			EstimatedDeliveryAt: res.EstimatedArrivalAt,
   331			TotalCostUnits:      route.TotalCost,
   332			CapacityUsed:        1,
   333			Valid:               true,
   334		}
   335		if err := app.Store.InsertJourney(ctx, j); err != nil {
   336			return nil, nil, err
   337		}
   338		if err := app.Store.AddJourneySample(ctx, jid, sm.ID); err != nil {
   339			return nil, nil, err
   340		}
   341	
   342		// reserve capacity
   343		cooled := route.NeedsCooled
   344		for _, n := range route.Nodes {
   345			loc, _ := app.Store.GetLocation(ctx, n)
   346			if loc == nil {
   347				continue
   348			}
   349			need := false
   350			if cooled {
   351				need = loc.CooledCapacity > 0
   352			} else {
   353				need = loc.CapacityUnits > 0
   354			}
   355			if need {
   356				if err := app.Store.ReserveCapacity(ctx, "location", n, sm.ID, jid, cooled, 1); err != nil {
   357					return nil, nil, err
   358				}
   359			}
   360		}
   361		for _, h := range route.Hops {
   362			c, _ := app.Store.GetConnection(ctx, h.ConnectionID)
   363			if c == nil {
   364				continue
   365			}
   366			need := false
   367			if cooled {
   368				need = c.CooledCapacity > 0
   369			} else {
   370				need = c.CapacityUnits > 0
   371			}
   372			if need {
   373				if err := app.Store.ReserveCapacity(ctx, "connection", h.ConnectionID, sm.ID, jid, cooled, 1); err != nil {
   374					return nil, nil, err
   375				}
   376			}
   377		}
   378	
   379		// stops
   380		seq := 1
   381		est := sm.RequestedAt
   382		if sm.EarliestCollectionAt.After(est) {
   383			est = sm.EarliestCollectionAt
   384		}
   385		// pickup
   386		pickupLoc := route.CollectionPoint
   387		plat, plng := sm.OriginLat, sm.OriginLng
   388		_ = app.Store.InsertStop(ctx, uuid.New(), jid, &pickupLoc, StopPickup, seq, est, 0, &plat, &plng)
   389		seq++
   390	
   391		// intermediate + delivery
   392		for i, node := range route.Nodes {
   393			loc, _ := app.Store.GetLocation(ctx, node)
   394			if loc == nil {
   395				continue
   396			}
   397			est = est.Add(time.Duration(loc.HandlingMinutes) * time.Minute)
   398			if i < len(route.Hops) {
   399				est = est.Add(time.Duration(route.Hops[i].Minutes) * time.Minute)
   400			}
   401			lat, lng := loc.Latitude, loc.Longitude
   402			stType := StopHandoff
   403			if node == route.Laboratory {
   404				stType = StopDelivery
   405			}
   406			_ = app.Store.InsertStop(ctx, uuid.New(), jid, &node, stType, seq, est, loc.HandlingMinutes, &lat, &lng)
   407			seq++
   408		}
   409	
   410		var asgs []Assignment
   411		aSeq := 1
   412	
   413		// collection assignment if not presealed and origin is home (or clinic needing collection)
   414		if !presealed && sm.OriginType == OriginHome {
   415			a := Assignment{
   416				ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindCollection,
   417				Sequence: aSeq, Status: StatusPending, ToLocationID: &route.CollectionPoint,
   418			}
   419			asgs = append(asgs, a)
   420			aSeq++
   421		}
   422	
   423		// node assignments at intermediate transfer/hub (not first if that's just CP pickup, not last lab)
   424		for i, node := range route.Nodes {
   425			loc, _ := app.Store.GetLocation(ctx, node)
   426			if loc == nil {
   427				continue
   428			}
   429			isLab := node == route.Laboratory
   430			isFirst := i == 0
   431			if isLab {
   432				continue
   433			}
   434			if isFirst && sm.OriginType == OriginHome && !presealed {
   435				// collection point receiving from home — still a node assignment
   436			}
   437			if loc.Functions.TransferPoint || loc.Functions.Hub || loc.Functions.CollectionPoint {
   438				nid := node
   439				var from, to *uuid.UUID
   440				if i > 0 {
   441					f := route.Nodes[i-1]
   442					from = &f
   443				}
   444				if i+1 < len(route.Nodes) {
   445					t := route.Nodes[i+1]
   446					to = &t
   447				}
   448				a := Assignment{
   449					ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindNode,
   450					Sequence: aSeq, Status: StatusPending, NodeID: &nid,
   451					FromLocationID: from, ToLocationID: to,
   452				}
   453				asgs = append(asgs, a)
   454				aSeq++
   455			}
   456		}
   457	
   458		// transport legs
   459		for _, h := range route.Hops {
   460			from, to := h.From, h.To
   461			a := Assignment{
   462				ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindTransport,
   463				Sequence: aSeq, Status: StatusPending, FromLocationID: &from, ToLocationID: &to,
   464			}
   465			asgs = append(asgs, a)
   466			aSeq++
   467		}
   468	
   469		// laboratory assignment
   470		labID := route.Laboratory
   471		a := Assignment{
   472			ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindLaboratory,
   473			Sequence: aSeq, Status: StatusPending, LaboratoryID: &labID, ToLocationID: &labID,
   474		}
   475		asgs = append(asgs, a)
   476	
   477		for i := range asgs {
   478			if err := app.Store.InsertAssignment(ctx, asgs[i]); err != nil {
   479				return nil, nil, err
   480			}
   481		}
   482	
   483		// offer first actionable assignment
   484		if err := app.offerNext(ctx, sm, asgs, st); err != nil {
   485			return nil, nil, err
   486		}
   487	
   488		sm.ActiveJourneyID = &jid
   489		sm.TargetLaboratoryID = &route.Laboratory
   490		if presealed {
   491			sm.Sealed = true
   492			t := now
   493			sm.SealedAt = &t
   494			sm.Status = StatusSealed
   495			sm.CurrentHolderID = &sm.RequesterID // will be overwritten by registrar
   496		} else {
   497			sm.Status = StatusRequested
   498		}
   499		if err := app.Store.UpdateSample(ctx, *sm); err != nil {
   500			return nil, nil, err
   501		}
   502	
   503		_, _ = app.Store.AddTimeline(ctx, "journey_created", actorID, role, "sample", sm.ID.String(), true, map[string]interface{}{
   504			"journeyId": jid.String(),
   505		})
   506		_, _ = app.Store.AddRealtime(ctx, "journey.created", "journey", jid.String(), map[string]interface{}{"sampleId": sm.ID.String()})
   507		return &j, asgs, nil
   508	}
   509	
   510	func (app *App) offerNext(ctx context.Context, sm *Sample, asgs []Assignment, st *SampleType) error {
   511		// find first pending assignment that is ready (prior completed or first)
   512		sort.Slice(asgs, func(i, j int) bool { return asgs[i].Sequence < asgs[j].Sequence })
   513		for i := range asgs {
   514			a := &asgs[i]
   515			if a.Status != StatusPending {
   516				continue
   517			}
   518			// skip if already offered and not expired
   519			if a.OfferedTo != nil && a.OfferExpiresAt != nil && a.OfferExpiresAt.After(time.Now()) {
   520				return nil
   521			}
   522			// prior must be completed or accepted for collection? collection can start first
   523			if i > 0 {
   524				prevDone := asgs[i-1].Status == StatusCompleted
   525				// allow offering next after previous accepted for pipeline, but typically after complete
   526				if !prevDone && asgs[i-1].Status != StatusAccepted && asgs[i-1].Status != StatusInProgress {
   527					// still offer collection first only
   528					if a.Kind != KindCollection {
   529						continue
   530					}
   531				}
   532			}
   533			worker, err := app.pickWorker(ctx, *a, st)
   534			if err != nil {
   535				return err
   536			}
   537			if worker == nil {
   538				// leave pending unoffered; exception later
   539				return nil
   540			}
   541			exp := time.Now().UTC().Add(OfferTimeout)
   542			a.OfferedTo = &worker.ID
   543			a.OfferExpiresAt = &exp
   544			if err := app.Store.UpdateAssignment(ctx, *a); err != nil {
   545				return err
   546			}
   547			_ = app.Store.MarkOffered(ctx, worker.ID)
   548			_, _ = app.Store.AddTimeline(ctx, "assignment_offered", "system", "system", "assignment", a.ID.String(), true, map[string]interface{}{
   549				"workerId": worker.ID.String(), "kind": a.Kind,
   550			})

