   192	func cors(next http.Handler) http.Handler {
   193		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   194			w.Header().Set("Access-Control-Allow-Origin", "*")
   195			w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
   196			w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
   197			if r.Method == http.MethodOptions {
   198				w.WriteHeader(204)
   199				return
   200			}
   201			next.ServeHTTP(w, r)
   202		})
