   794		case RoleDeliveryPartner:
   795			return kind == KindTransport
   796		case RoleNodeHandler:
   797			return kind == KindNode
   798		case RoleLaboratoryTeam:
   799			return kind == KindLaboratory
   800		}
   801		return true
