  1721	func (app *App) handleDisruption(w http.ResponseWriter, r *http.Request) {
  1722		auth := getAuth(r)
  1723		if !roleSelected(auth) {
  1724			writeErr(w, 409, "role_not_selected", "select a role")
  1725			return
  1726		}
  1727		if !adminOrDispatcher(auth) {
  1728			writeErr(w, 403, "forbidden", "forbidden")
  1729			return
  1730		}
  1731		var req struct {
  1732			ResourceType   string `json:"resourceType"`
  1733			ResourceID     string `json:"resourceId"`
  1734			Reason         string `json:"reason"`
  1735			OccurredAt     string `json:"occurredAt"`
  1736			IdempotencyKey string `json:"idempotencyKey"`
  1737		}
  1738		if err := decodeJSON(r, &req); err != nil {
  1739			writeErr(w, 400, "invalid_json", "invalid json")
  1740			return
  1741		}
  1742		if req.ResourceType == "" || req.ResourceID == "" {
  1743			writeErr(w, 400, "invalid_json", "resource required")
  1744			return
  1745		}
  1746		at := time.Now().UTC()
  1747		if req.OccurredAt != "" {
  1748			t, err := parseTime(req.OccurredAt)
  1749			if err != nil {
  1750				writeErr(w, 400, "invalid_time", "invalid occurredAt")
  1751				return
  1752			}
  1753			at = t
  1754		}
  1755		// deactivate resource if applicable
  1756		if id, err := uuid.Parse(req.ResourceID); err == nil {
  1757			switch req.ResourceType {
  1758			case "node", "location", "laboratory":
  1759				_ = app.Store.SetLocationActive(r.Context(), id, false)
  1760				_, _ = app.Store.BumpNetworkRevision(r.Context())
  1761				go app.rebuildServiceabilitySnapshot(r.Context())
  1762			case "connection", "route":
  1763				_ = app.Store.SetConnectionActive(r.Context(), id, false)
  1764				_, _ = app.Store.BumpNetworkRevision(r.Context())
  1765				go app.rebuildServiceabilitySnapshot(r.Context())
  1766			case "worker":
  1767				u, _ := app.Store.GetUserByID(r.Context(), id)
  1768				if u != nil {
  1769					_ = app.Store.SetWorkerAvailability(r.Context(), id, false, u.CapacityUnits)
  1770				}
  1771			}
  1772		}
  1773		affected := app.findAffectedJourneys(r.Context(), req.ResourceType, req.ResourceID)
  1774		var results []map[string]any
  1775		for _, j := range affected {
  1776			// replan each
  1777			sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
  1778			if len(sids) == 0 {
  1779				continue
  1780			}
  1781			sm, _ := app.Store.GetSample(r.Context(), sids[0])
  1782			if sm == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled {
  1783				continue
  1784			}
  1785			holder := sm.CurrentHolderID
  1786			st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
  1787			origin := Coordinate{Latitude: sm.OriginLat, Longitude: sm.OriginLng}
  1788			if sm.LatestLat != nil {
  1789				origin = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
  1790			}
  1791			res, _ := app.computeServiceability(r.Context(), origin, OriginNode, sm.OriginNodeID, sm.SampleTypeID, time.Now().UTC(), sm.DeliveryDeadline, sm.EarliestCollectionAt, sm.LatestCollectionAt, st != nil && st.RequiresCooledRoute)
  1792			j.PlanVersion++
  1793			if !res.Serviceable {
  1794				sm.Status = StatusExpired
  1795				sm.CurrentHolderID = holder
  1796				_ = app.Store.UpdateSample(r.Context(), *sm)
  1797				rs := "expired"
  1798				j.ReplanStatus = &rs
  1799				j.Valid = false
  1800				_ = app.Store.UpdateJourney(r.Context(), j)
  1801				results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "expired"})
  1802				continue
  1803			}
  1804			asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
  1805			for _, a := range asgs {
  1806				if a.Status != StatusCompleted {
  1807					a.Status = StatusCancelled
  1808					a.OfferedTo = nil
  1809					_ = app.Store.UpdateAssignment(r.Context(), a)
  1810				}
  1811			}
  1812			rs := "replanned"
  1813			j.ReplanStatus = &rs
  1814			j.Valid = true
  1815			_ = app.Store.UpdateJourney(r.Context(), j)
  1816			sm.CurrentHolderID = holder
  1817			_ = app.Store.UpdateSample(r.Context(), *sm)
  1818			results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "replanned", "planVersion": j.PlanVersion})
  1819		}
  1820		if results == nil {
  1821			results = []map[string]any{}
  1822		}
  1823		_ = at
  1824		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
  1825		writeData(w, 200, map[string]any{"affected": results})
  1826	}
  1827	
  1828	func (app *App) findAffectedJourneys(ctx context.Context, resourceType, resourceID string) []Journey {
  1829		samples, _ := app.Store.ListSamples(ctx)
  1830		seen := map[uuid.UUID]bool{}
  1831		var out []Journey
  1832		rid, _ := uuid.Parse(resourceID)
  1833		for _, sm := range samples {
  1834			if sm.ActiveJourneyID == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired {
  1835				continue
  1836			}
  1837			if seen[*sm.ActiveJourneyID] {
  1838				continue
  1839			}
  1840			hit := false
  1841			if resourceType == "worker" && sm.CurrentHolderID != nil && sm.CurrentHolderID.String() == resourceID {
  1842				hit = true
  1843			}
  1844			if (resourceType == "laboratory" || resourceType == "node" || resourceType == "location") && sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID == rid {
  1845				hit = true
  1846			}
  1847			asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
  1848			for _, a := range asgs {
  1849				if a.Status == StatusCompleted {
  1850					continue
  1851				}
  1852				if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
  1853					hit = true
  1854				}
  1855				if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
  1856					((a.NodeID != nil && *a.NodeID == rid) || (a.LaboratoryID != nil && *a.LaboratoryID == rid) ||
  1857						(a.FromLocationID != nil && *a.FromLocationID == rid) || (a.ToLocationID != nil && *a.ToLocationID == rid)) {
  1858					hit = true
  1859				}
  1860			}
  1861			if hit {
  1862				j, _ := app.Store.GetJourney(ctx, *sm.ActiveJourneyID)
  1863				if j != nil {
  1864					seen[j.ID] = true
  1865					out = append(out, *j)
  1866				}
  1867			}
  1868		}
  1869		sort.Slice(out, func(i, k int) bool { return out[i].ID.String() < out[k].ID.String() })
  1870		return out
  1871	}

