   125	func normalizeAudit(raw bson.M) map[string]any {
   126		str := func(keys ...string) string {
   127			for _, k := range keys {
   128				if v, ok := raw[k]; ok && v != nil {
   129					switch t := v.(type) {
   130					case string:
   131						return t
   132					}
   133				}
   134			}
   135			return ""
   136		}
   137		occurred := ""
   138		for _, k := range []string{"occurredAt", "occurred_at"} {
   139			if v, ok := raw[k]; ok {
   140				switch t := v.(type) {
   141				case time.Time:
   142					occurred = fmtTime(t)
   143				case bson.DateTime:
   144					occurred = fmtTime(t.Time())
   145				}
   146			}
