   112	func requireRole(auth *AuthContext, roles ...string) bool {
   113		if auth == nil {
   114			return false
   115		}
   116		if auth.ActiveRole == "" {
   117			return false
   118		}
   119		for _, role := range roles {
   120			if auth.ActiveRole == role {
   121				return true
   122			}
   123		}
   124		return false
   125	}
