    97			if err != nil || sess == nil || time.Now().After(sess.ExpiresAt) {
    98				writeErr(w, 401, "unauthorized", "invalid token")
    99				return
   100			}
   101			u, err := app.Store.GetUserByID(r.Context(), sess.UserID)
   102			if err != nil || u == nil || !u.Active {
   103				writeErr(w, 401, "unauthorized", "invalid user")
   104				return
   105			}
   106			auth := &AuthContext{User: *u, Session: *sess, ActiveRole: sess.ActiveRole}
   107			ctx := context.WithValue(r.Context(), authKey, auth)
   108			next(w, r.WithContext(ctx))
