   751		if req.CapacityUnits < 0 {
   752			writeErr(w, 400, "invalid_capacity", "invalid capacity")
   753			return
   754		}
   755		cooled := 0
   756		if req.CooledCapacityUnits != nil {
   757			if *req.CooledCapacityUnits < 0 {
   758				writeErr(w, 400, "invalid_capacity", "invalid cooled capacity")
   759				return
   760			}
   761			cooled = *req.CooledCapacityUnits
