   839	func (app *App) canSeeSample(auth *AuthContext, sm *Sample) bool {
   840		if auth == nil || sm == nil {
   841			return false
   842		}
   843		if requireRole(auth, RoleAdministrator, RoleDispatcher) {
   844			return true
   845		}
   846		if requireRole(auth, RoleRequester) && sm.RequesterID == auth.User.ID {
   847			return true
   848		}
   849		if sm.CurrentHolderID != nil && *sm.CurrentHolderID == auth.User.ID {
   850			return true
   851		}
   852		asgs, _ := app.Store.ListAssignmentsForSample(context.Background(), sm.ID)
   853		for _, a := range asgs {
   854			if a.WorkerID != nil && *a.WorkerID == auth.User.ID {
   855				return true
   856			}
   857			if a.OfferedTo != nil && *a.OfferedTo == auth.User.ID {
   858				return true
   859			}
   860		}
   861		return false
   862	}
