   864	func (app *App) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
   865		auth := getAuth(r)
   866		if !roleSelected(auth) {
   867			writeErr(w, 409, "role_not_selected", "select a role")
   868			return
   869		}
   870		sid, err := uuid.Parse(r.PathValue("sampleId"))
   871		if err != nil {
   872			writeErr(w, 404, "not_found", "not found")
   873			return
   874		}
   875		sm, _ := app.Store.GetSample(r.Context(), sid)
   876		if sm == nil {
   877			writeErr(w, 404, "not_found", "not found")
   878			return
   879		}
   880		if !app.canSeeSample(auth, sm) {
   881			writeErr(w, 403, "forbidden", "forbidden")
   882			return
   883		}
   884		writeData(w, 200, app.sampleStatePayload(r.Context(), *sm, auth))
   885	}
