   512			IdempotencyKey         string  `json:"idempotencyKey"`
   513		}
   514		if err := decodeJSON(r, &req); err != nil {
   515			writeErr(w, 400, "invalid_json", "invalid json")
   516			return
   517		}
   518		if req.ContainerType == "" {
   519			writeErr(w, 400, "invalid_json", "container required")
   520			return
   521		}
   522		sid, err := uuid.Parse(req.SampleID)
