   526		}
   527		aid, err := uuid.Parse(req.AssignmentID)
   528		if err != nil {
   529			writeErr(w, 404, "not_found", "not found")
   530			return
   531		}
   532		at, err := parseTime(req.RecordedAt)
   533		if err != nil {
   534			writeErr(w, 400, "invalid_time", "invalid recordedAt")
   535			return
   536		}
   537		sm, _ := app.Store.GetSample(r.Context(), sid)
   538		if sm == nil {
   539			writeErr(w, 404, "not_found", "sample")
   540			return
   541		}
   542		if sm.CurrentHolderID == nil || *sm.CurrentHolderID != auth.User.ID {
   543			writeErr(w, 409, "not_current_holder", "not current holder")
   544			return
   545		}
   546		var locID *uuid.UUID
   547		if req.LocationID != nil && *req.LocationID != "" {
   548			id, err := uuid.Parse(*req.LocationID)
   549			if err != nil {
   550				writeErr(w, 400, "invalid_json", "invalid location")
