   552			}
   553			locID = &id
   554		}
   555		compliant := req.ContainerType == sm.ContainerType &&
   556			req.ObservedTemperatureC >= sm.TemperatureMinC &&
   557			req.ObservedTemperatureC <= sm.TemperatureMaxC
   558		cid := uuid.New()
