   560			writeErr(w, 500, "internal_error", "insert")
   561			return
   562		}
   563		if !compliant {
   564			sm.Status = StatusException
   565			sm.Exception = map[string]interface{}{
   566				"reason":                 "handling_checkpoint_violation",
   567				"containerType":          req.ContainerType,
