   582		if !roleSelected(auth) {
   583			writeErr(w, 409, "role_not_selected", "select a role")
   584			return
   585		}
   586		var req struct {
   587			AssignmentID string     `json:"assignmentId"`
   588			Coordinate   Coordinate `json:"coordinate"`
   589			RecordedAt   string     `json:"recordedAt"`
   590			Sequence     int        `json:"sequence"`
   591		}
   592		if err := decodeJSON(r, &req); err != nil {
   593			writeErr(w, 400, "invalid_json", "invalid json")
   594			return
   595		}
   596		if !validCoord(req.Coordinate) {
   597			writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
   598			return
   599		}
   600		if req.Sequence < 1 {
   601			writeErr(w, 400, "invalid_json", "sequence must be >= 1")
   602			return
   603		}
   604		at, err := parseTime(req.RecordedAt)
   605		if err != nil {
   606			writeErr(w, 400, "invalid_time", "invalid recordedAt")
   607			return
   608		}
   609		aid, err := uuid.Parse(req.AssignmentID)
   610		if err != nil {
   611			writeErr(w, 404, "not_found", "not found")
   612			return
   613		}
   614		a, _ := app.Store.GetAssignment(r.Context(), aid)
   615		if a == nil {
   616			writeErr(w, 404, "not_found", "assignment")
   617			return
   618		}
   619		if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
   620			writeErr(w, 403, "forbidden", "not your assignment")
   621			return
   622		}
   623		last, err := app.Store.LastWorkerLocSeq(r.Context(), aid)
   624		if err != nil {
   625			writeErr(w, 500, "internal_error", "seq")
   626			return
   627		}
   628		if req.Sequence <= last {
   629			writeErr(w, 409, "stale_location", "sequence not increasing")
   630			return
   631		}
   632		if err := app.Store.InsertWorkerLocation(r.Context(), auth.User.ID, aid, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, at); err != nil {
   633			writeErr(w, 500, "internal_error", "insert")
   634			return
   635		}
   636		sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
   637		if sm != nil && sm.CurrentHolderID != nil && *sm.CurrentHolderID == auth.User.ID {
   638			sm.LatestLat = &req.Coordinate.Latitude
   639			sm.LatestLng = &req.Coordinate.Longitude
   640			sm.LocationRecordedAt = &at
   641			_ = app.Store.UpdateSample(r.Context(), *sm)
   642		}
   643		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "record_location", "assignment", aid.String(), true, nil)
   644		writeData(w, 200, map[string]any{"assignmentId": aid.String(), "sequence": req.Sequence})
   645	}
