   647	func (app *App) handleProgress(w http.ResponseWriter, r *http.Request) {
   648		auth := getAuth(r)
   649		if !roleSelected(auth) {
   650			writeErr(w, 409, "role_not_selected", "select a role")
   651			return
   652		}
   653		var req struct {
   654			AssignmentID   string `json:"assignmentId"`
   655			Status         string `json:"status"`
   656			Note           string `json:"note"`
   657			IdempotencyKey string `json:"idempotencyKey"`
   658		}
   659		if err := decodeJSON(r, &req); err != nil {
   660			writeErr(w, 400, "invalid_json", "invalid json")
   661			return
   662		}
   663		if req.Status != StatusInProgress && req.Status != StatusCompleted {
   664			writeErr(w, 400, "invalid_json", "invalid status")
   665			return
   666		}
   667		aid, err := uuid.Parse(req.AssignmentID)
   668		if err != nil {
   669			writeErr(w, 404, "not_found", "not found")
   670			return
   671		}
   672		a, _ := app.Store.GetAssignment(r.Context(), aid)
   673		if a == nil {
   674			writeErr(w, 404, "not_found", "not found")
   675			return
   676		}
   677		if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
   678			writeErr(w, 403, "forbidden", "not your assignment")
   679			return
   680		}
   681		now := time.Now().UTC()
   682		a.Status = req.Status
   683		if req.Status == StatusCompleted {
   684			a.CompletedAt = &now
   685		}
   686		_ = app.Store.UpdateAssignment(r.Context(), *a)
   687		sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
   688		if sm != nil && req.Status == StatusInProgress {
   689			if a.Kind == KindTransport {
   690				sm.Status = StatusInTransit
   691			} else if a.Kind == KindCollection {
   692				sm.Status = StatusCollecting
   693			}
   694			_ = app.Store.UpdateSample(r.Context(), *sm)
   695		}
   696		if sm != nil && req.Status == StatusCompleted {
   697			st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
   698			all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
   699			_ = app.offerNext(r.Context(), sm, all, st)
   700		}

