   287	func spaHandler(dir string) http.HandlerFunc {
   288		return func(w http.ResponseWriter, r *http.Request) {
   289			if strings.HasPrefix(r.URL.Path, "/api/") || r.URL.Path == "/ready" {
   290				http.NotFound(w, r)
   291				return
   292			}
   293			p := filepath.Join(dir, filepath.Clean(r.URL.Path))
   294			if !strings.HasPrefix(p, dir) {
   295				http.NotFound(w, r)
   296				return
   297			}
   298			if st, err := os.Stat(p); err == nil && !st.IsDir() {
   299				http.ServeFile(w, r, p)
   300				return
   301			}
   302			index := filepath.Join(dir, "index.html")
   303			if _, err := os.Stat(index); err == nil {
   304				http.ServeFile(w, r, index)
   305				return
   306			}
   307			http.NotFound(w, r)
   308		}
