   271		}
   272		if err := app.Store.InsertHandoff(r.Context(), h); err != nil {
   273			writeErr(w, 500, "internal_error", "insert")
   274			return
   275		}
   276		sm.PendingHandoffID = &h.ID
   277		_ = app.Store.UpdateSample(r.Context(), *sm)
   278		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "initiate_handoff", "sample", sid.String(), true, map[string]interface{}{"handoffId": h.ID.String()})
