   493		}
   494		if !requireRole(auth, RoleAdministrator) {
   495			writeErr(w, 403, "forbidden", "forbidden")
   496			return
   497		}
   498		var req struct {
   499			Name            string     `json:"name"`
   500			Coordinate      Coordinate `json:"coordinate"`
   501			CoverageKm      *float64   `json:"coverageKm"`
   502			HandlingMinutes *int       `json:"handlingMinutes"`
   503			Active          bool       `json:"active"`
   504			Functions       []string   `json:"functions"`
   505		}
   506		if err := decodeJSON(r, &req); err != nil {
   507			writeErr(w, 400, "invalid_json", "invalid json")
   508			return
   509		}
   510		if req.Name == "" || !validCoord(req.Coordinate) {
   511			writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
   512			return
   513		}
   514		cov := 5.0
   515		if req.CoverageKm != nil {
   516			cov = *req.CoverageKm
   517		}
   518		if cov <= 0 || cov > 5 {
   519			writeErr(w, 400, "invalid_node_coverage", "coverage must be in (0, 5]")
   520			return
   521		}
   522		hm := 0
   523		if req.HandlingMinutes != nil {
   524			hm = *req.HandlingMinutes
   525		}
   526		if hm < 0 || hm > 1440 {
   527			writeErr(w, 400, "invalid_handling_time", "invalid handling time")
   528			return
   529		}
   530		if len(req.Functions) == 0 {
   531			writeErr(w, 400, "invalid_location_function", "functions required")
   532			return
   533		}
   534		fns, ok := parseFunctions(req.Functions)
   535		if !ok {
   536			writeErr(w, 400, "invalid_location_function", "invalid function")
   537			return
   538		}
   539		l := Location{
