   541			CoverageKm: cov, HandlingMinutes: hm, Active: req.Active, Functions: fns,
   542			CapacityUnits: 10, CooledCapacity: 10,
   543		}
   544		if err := app.Store.InsertLocation(r.Context(), l); err != nil {
