    13	func (app *App) writeAudit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
    14		if details == nil {
    15			details = map[string]interface{}{}
    16		}
    17		now := time.Now().UTC()
    18		id := uuid.New().String()
    19		doc := bson.M{
    20			"auditId":    id,
    21			"audit_id":   id,
    22			"actorId":    actorID,
    23			"actor_id":   actorID,
    24			"role":       role,
    25			"actorRole":  role,
    26			"action":     action,
    27			"entityType": entityType,
    28			"entity_type": entityType,
    29			"entityId":   entityID,
    30			"entity_id":  entityID,
    31			"success":    success,
    32			"occurredAt": now,
    33			"occurred_at": now,
    34			"details":    details,
    35		}
    36		_, _ = app.Store.Audit.InsertOne(ctx, doc)
    37		_, _ = app.Store.AddTimeline(ctx, action, actorID, role, entityType, entityID, success, details)
    38	}
    39	
    40	type AuditQuery struct {
    41		Query      string
    42		ActorID    string
    43		EntityType string
    44		EntityID   string
    45		Action     string
    46		Role       string
    47		Success    *bool
    48		FromTime   *time.Time
    49		ToTime     *time.Time
    50		Limit      int
    51		Offset     int
    52		Order      string
    53	}
    54	
    55	func (app *App) searchAudit(ctx context.Context, q AuditQuery) ([]map[string]any, int, error) {
    56		filter := bson.M{}
    57		if q.ActorID != "" {
    58			filter["actorId"] = q.ActorID
    59		}
    60		if q.EntityType != "" {
    61			filter["entityType"] = q.EntityType
    62		}
    63		if q.EntityID != "" {
    64			filter["entityId"] = q.EntityID
    65		}
    66		if q.Action != "" {
    67			filter["action"] = q.Action
    68		}
    69		if q.Role != "" {
    70			filter["role"] = q.Role
    71		}
    72		if q.Success != nil {
    73			filter["success"] = *q.Success
    74		}
    75		if q.FromTime != nil || q.ToTime != nil {
    76			rng := bson.M{}
    77			if q.FromTime != nil {
    78				rng["$gte"] = *q.FromTime
    79			}
    80			if q.ToTime != nil {
    81				rng["$lte"] = *q.ToTime
    82			}
    83			filter["occurredAt"] = rng
    84		}
    85		if q.Query != "" {
    86			// text-ish match across a few fields
    87			rx := bson.M{"$regex": q.Query, "$options": "i"}
    88			filter["$or"] = []bson.M{
    89				{"action": rx},
    90				{"entityType": rx},
    91				{"entityId": rx},
    92				{"actorId": rx},
    93				{"role": rx},
    94			}
    95		}
    96		total, err := app.Store.Audit.CountDocuments(ctx, filter)
    97		if err != nil {
    98			return nil, 0, err
    99		}
   100		sortDir := -1
   101		if q.Order == "oldest_first" {
   102			sortDir = 1
   103		}
   104		opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: sortDir}}).SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
   105		cur, err := app.Store.Audit.Find(ctx, filter, opts)
   106		if err != nil {
   107			return nil, 0, err
   108		}
   109		defer cur.Close(ctx)
   110		var entries []map[string]any
   111		for cur.Next(ctx) {
   112			var raw bson.M
   113			if err := cur.Decode(&raw); err != nil {
   114				continue
   115			}
   116			entries = append(entries, normalizeAudit(raw))
   117		}
   118		if entries == nil {
   119			entries = []map[string]any{}
   120		}
   121		_ = strings.TrimSpace
   122		return entries, int(total), nil
   123	}
   124	
   125	func normalizeAudit(raw bson.M) map[string]any {
   126		str := func(keys ...string) string {
   127			for _, k := range keys {
   128				if v, ok := raw[k]; ok && v != nil {
   129					switch t := v.(type) {
   130					case string:
   131						return t
   132					}
   133				}
   134			}
   135			return ""
   136		}
   137		occurred := ""
   138		for _, k := range []string{"occurredAt", "occurred_at"} {
   139			if v, ok := raw[k]; ok {
   140				switch t := v.(type) {
   141				case time.Time:
   142					occurred = fmtTime(t)
   143				case bson.DateTime:
   144					occurred = fmtTime(t.Time())
   145				}
   146			}
   147		}
   148		success, _ := raw["success"].(bool)
   149		details := map[string]any{}
   150		if d, ok := raw["details"].(bson.M); ok {
   151			for k, v := range d {
   152				details[k] = v
   153			}
   154		} else if d, ok := raw["details"].(map[string]any); ok {
   155			details = d
   156		}
   157		id := str("auditId", "audit_id")
   158		actor := str("actorId", "actor_id")
   159		role := str("role", "actorRole")
   160		return map[string]any{
   161			"auditId":    id,
   162			"audit_id":   id,
   163			"actorId":    actor,
   164			"actor_id":   actor,
   165			"role":       role,
   166			"actorRole":  role,
   167			"action":     str("action"),
   168			"entityType": str("entityType", "entity_type"),
   169			"entity_type": str("entityType", "entity_type"),
   170			"entityId":   str("entityId", "entity_id"),
   171			"entity_id":  str("entityId", "entity_id"),
   172			"success":    success,
   173			"occurredAt": occurred,
   174			"occurred_at": occurred,
   175			"details":    details,
   176		}
   177	}
