   350				if from != nil && from.Status != StatusCompleted {
   351					from.Status = StatusCompleted
   352					from.CompletedAt = &now
   353					_ = app.Store.UpdateAssignment(r.Context(), *from)
   354				}
   355				if to != nil && to.Status == StatusAccepted {
   356					to.Status = StatusInProgress
   357					_ = app.Store.UpdateAssignment(r.Context(), *to)
   358				}
   359				if to != nil {
   360					switch to.Kind {
