   510	func (app *App) offerNext(ctx context.Context, sm *Sample, asgs []Assignment, st *SampleType) error {
   511		// find first pending assignment that is ready (prior completed or first)
   512		sort.Slice(asgs, func(i, j int) bool { return asgs[i].Sequence < asgs[j].Sequence })
   513		for i := range asgs {
   514			a := &asgs[i]
   515			if a.Status != StatusPending {
   516				continue
   517			}
   518			// skip if already offered and not expired
   519			if a.OfferedTo != nil && a.OfferExpiresAt != nil && a.OfferExpiresAt.After(time.Now()) {
   520				return nil
   521			}
   522			// prior must be completed or accepted for collection? collection can start first
   523			if i > 0 {
   524				prevDone := asgs[i-1].Status == StatusCompleted
   525				// allow offering next after previous accepted for pipeline, but typically after complete
   526				if !prevDone && asgs[i-1].Status != StatusAccepted && asgs[i-1].Status != StatusInProgress {
   527					// still offer collection first only
   528					if a.Kind != KindCollection {
   529						continue
   530					}
   531				}
   532			}
   533			worker, err := app.pickWorker(ctx, *a, st)
   534			if err != nil {
   535				return err
   536			}
   537			if worker == nil {
   538				// leave pending unoffered; exception later
   539				return nil
   540			}
   541			exp := time.Now().UTC().Add(OfferTimeout)
   542			a.OfferedTo = &worker.ID
   543			a.OfferExpiresAt = &exp
   544			if err := app.Store.UpdateAssignment(ctx, *a); err != nil {
   545				return err
   546			}
   547			_ = app.Store.MarkOffered(ctx, worker.ID)
   548			_, _ = app.Store.AddTimeline(ctx, "assignment_offered", "system", "system", "assignment", a.ID.String(), true, map[string]interface{}{
   549				"workerId": worker.ID.String(), "kind": a.Kind,
   550			})
   551			_, _ = app.Store.AddRealtime(ctx, "assignment.offered", "assignment", a.ID.String(), map[string]interface{}{
   552				"workerId": worker.ID.String(),
   553			})
   554			if sm.Status == StatusRequested {
   555				sm.Status = StatusOffered
   556				_ = app.Store.UpdateSample(ctx, *sm)
   557			}
   558			return nil
   559		}
   560		return nil
   561	}
