  1428			return
  1429		}
  1430		if req.ExpectedPlanVersion != j.PlanVersion {
  1431			writeErr(w, 409, "stale_plan", "stale plan version")
  1432			return
  1433		}
  1434		if j.Status == StatusCompleted {
  1435			writeErr(w, 409, "invalid_state", "already completed")
  1436			return
  1437		}
  1438		j.PlanVersion++
  1439		j.Status = StatusCancelled
  1440		_ = app.Store.UpdateJourney(r.Context(), *j)
  1441		asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
  1442		for _, a := range asgs {
