  1444				a.Status = StatusCancelled
  1445				a.OfferedTo = nil
  1446				_ = app.Store.UpdateAssignment(r.Context(), a)
  1447			}
  1448		}
  1449		sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
  1450		for _, sid := range sids {
