  1462	func (app *App) replanJourney(w http.ResponseWriter, r *http.Request, jid uuid.UUID, expected int, reason string) {
  1463		auth := getAuth(r)
  1464		j, _ := app.Store.GetJourney(r.Context(), jid)
  1465		if j == nil {
  1466			writeErr(w, 404, "not_found", "not found")
  1467			return
  1468		}
  1469		if expected != j.PlanVersion {
  1470			writeErr(w, 409, "stale_plan", "stale plan version")
  1471			return
  1472		}
  1473		if j.Status == StatusCompleted || j.Status == StatusCancelled {
  1474			writeErr(w, 409, "invalid_state", "cannot replan completed")
  1475			return
  1476		}
  1477		sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
  1478		if len(sids) == 0 {
  1479			writeErr(w, 409, "invalid_state", "no samples")
  1480			return
  1481		}
  1482		sm, _ := app.Store.GetSample(r.Context(), sids[0])
  1483		if sm == nil {
  1484			writeErr(w, 404, "not_found", "sample")
  1485			return
  1486		}
  1487		// preserve holder and completed work
  1488		holder := sm.CurrentHolderID
  1489		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
  1490		origin := Coordinate{Latitude: sm.OriginLat, Longitude: sm.OriginLng}
  1491		if sm.LatestLat != nil {
  1492			origin.Latitude = *sm.LatestLat
  1493			origin.Longitude = *sm.LatestLng
  1494		}
  1495		originType := sm.OriginType
  1496		if sm.Sealed {
  1497			originType = OriginNode
  1498		}
  1499		res, err := app.computeServiceability(r.Context(), origin, originType, sm.OriginNodeID, sm.SampleTypeID, time.Now().UTC(), sm.DeliveryDeadline, sm.EarliestCollectionAt, sm.LatestCollectionAt, st != nil && st.RequiresCooledRoute)
  1500		if err != nil {
  1501			writeErr(w, 500, "internal_error", "compute")
  1502			return
  1503		}
  1504		j.PlanVersion++
  1505		if !res.Serviceable {
  1506			j.Valid = false
  1507			rs := "expired"
  1508			j.ReplanStatus = &rs
  1509			sm.Status = StatusExpired
  1510			sm.Serviceability = "unserviceable"
  1511			sm.ServiceabilityReason = res.Reason
  1512			sm.CurrentHolderID = holder
  1513			_ = app.Store.UpdateSample(r.Context(), *sm)
  1514			_ = app.Store.UpdateJourney(r.Context(), *j)
  1515			app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "replan", "journey", j.ID.String(), true, map[string]interface{}{"result": "expired", "reason": reason})
  1516			writeData(w, 200, map[string]any{"journeyId": j.ID.String(), "planVersion": j.PlanVersion, "status": "expired", "replanStatus": "expired"})
  1517			return
  1518		}
  1519		// cancel unfinished assignments, keep completed
  1520		asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
  1521		maxSeq := 0
  1522		for _, a := range asgs {
  1523			if a.Status == StatusCompleted && a.Sequence > maxSeq {
  1524				maxSeq = a.Sequence
  1525			}
  1526			if a.Status != StatusCompleted {
  1527				a.Status = StatusCancelled
  1528				a.OfferedTo = nil
  1529				_ = app.Store.UpdateAssignment(r.Context(), a)
  1530			}
  1531		}
  1532		_ = app.Store.DeleteUncompletedStops(r.Context(), j.ID)
  1533		_ = app.Store.ReleaseReservationsForSample(r.Context(), sm.ID)
  1534	
  1535		// recreate unfinished legs from remaining route
  1536		route := res.Route
  1537		cooled := route.NeedsCooled
  1538		for _, n := range route.Nodes {
  1539			loc, _ := app.Store.GetLocation(r.Context(), n)
  1540			if loc == nil {
  1541				continue
  1542			}
  1543			need := false
  1544			if cooled {
  1545				need = loc.CooledCapacity > 0
  1546			} else {
  1547				need = loc.CapacityUnits > 0
  1548			}
  1549			if need {
  1550				_ = app.Store.ReserveCapacity(r.Context(), "location", n, sm.ID, j.ID, cooled, 1)
  1551			}
  1552		}
  1553		seq := maxSeq + 1
  1554		var newAsgs []Assignment
  1555		for _, h := range route.Hops {
  1556			from, to := h.From, h.To
  1557			a := Assignment{
  1558				ID: uuid.New(), JourneyID: j.ID, SampleID: sm.ID, Kind: KindTransport,
  1559				Sequence: seq, Status: StatusPending, FromLocationID: &from, ToLocationID: &to,
  1560			}
  1561			_ = app.Store.InsertAssignment(r.Context(), a)
  1562			newAsgs = append(newAsgs, a)
  1563			seq++
  1564		}
  1565		labID := route.Laboratory
  1566		la := Assignment{
  1567			ID: uuid.New(), JourneyID: j.ID, SampleID: sm.ID, Kind: KindLaboratory,
  1568			Sequence: seq, Status: StatusPending, LaboratoryID: &labID, ToLocationID: &labID,
  1569		}
  1570		_ = app.Store.InsertAssignment(r.Context(), la)
  1571		newAsgs = append(newAsgs, la)
  1572	
  1573		sm.TargetLaboratoryID = &route.Laboratory
  1574		sm.CurrentHolderID = holder
  1575		sm.ActiveJourneyID = &j.ID
  1576		_ = app.Store.UpdateSample(r.Context(), *sm)
  1577		all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
  1578		_ = app.offerNext(r.Context(), sm, all, st)
  1579		j.Valid = true
  1580		rs := "replanned"
  1581		j.ReplanStatus = &rs
  1582		j.EstimatedDeliveryAt = res.EstimatedArrivalAt
  1583		j.TotalCostUnits = route.TotalCost
  1584		_ = app.Store.UpdateJourney(r.Context(), *j)
  1585		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "replan", "journey", j.ID.String(), true, map[string]interface{}{"reason": reason})
  1586		writeData(w, 200, map[string]any{"journeyId": j.ID.String(), "planVersion": j.PlanVersion, "status": j.Status, "replanStatus": "replanned"})
