  1923	func (app *App) findAffectedJourneys(ctx context.Context, resourceType, resourceID string) []Journey {
  1924		samples, _ := app.Store.ListSamples(ctx)
  1925		seen := map[uuid.UUID]bool{}
  1926		var out []Journey
  1927		rid, _ := uuid.Parse(resourceID)
  1928		for _, sm := range samples {
  1929			if sm.ActiveJourneyID == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired {
  1930				continue
  1931			}
  1932			if seen[*sm.ActiveJourneyID] {
  1933				continue
  1934			}
  1935			hit := false
  1936			if resourceType == "worker" && sm.CurrentHolderID != nil && sm.CurrentHolderID.String() == resourceID {
  1937				hit = true
  1938			}
  1939			if (resourceType == "laboratory" || resourceType == "node" || resourceType == "location") && sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID == rid {
  1940				hit = true
  1941			}
  1942			asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
  1943			for _, a := range asgs {
  1944				if a.Status == StatusCompleted {
  1945					continue
  1946				}
  1947				if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
  1948					hit = true
  1949				}
  1950				if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
  1951					((a.NodeID != nil && *a.NodeID == rid) || (a.LaboratoryID != nil && *a.LaboratoryID == rid) ||
  1952						(a.FromLocationID != nil && *a.FromLocationID == rid) || (a.ToLocationID != nil && *a.ToLocationID == rid)) {
  1953					hit = true
  1954				}
  1955			}
  1956			if hit {
  1957				j, _ := app.Store.GetJourney(ctx, *sm.ActiveJourneyID)
  1958				if j != nil {
  1959					seen[j.ID] = true
  1960					out = append(out, *j)
  1961				}
  1962			}
  1963		}
  1964		sort.Slice(out, func(i, k int) bool { return out[i].ID.String() < out[k].ID.String() })
  1965		return out
  1966	}

