    55	func (app *App) searchAudit(ctx context.Context, q AuditQuery) ([]map[string]any, int, error) {
    56		filter := bson.M{}
    57		if q.ActorID != "" {
    58			filter["actorId"] = q.ActorID
    59		}
    60		if q.EntityType != "" {
    61			filter["entityType"] = q.EntityType
    62		}
    63		if q.EntityID != "" {
    64			filter["entityId"] = q.EntityID
    65		}
    66		if q.Action != "" {
    67			filter["action"] = q.Action
    68		}
    69		if q.Role != "" {
    70			filter["role"] = q.Role
    71		}
    72		if q.Success != nil {
    73			filter["success"] = *q.Success
    74		}
    75		if q.FromTime != nil || q.ToTime != nil {
    76			rng := bson.M{}
    77			if q.FromTime != nil {
    78				rng["$gte"] = *q.FromTime
    79			}
    80			if q.ToTime != nil {
    81				rng["$lte"] = *q.ToTime
    82			}
    83			filter["occurredAt"] = rng
    84		}
    85		if q.Query != "" {
    86			// text-ish match across a few fields
    87			rx := bson.M{"$regex": q.Query, "$options": "i"}
    88			filter["$or"] = []bson.M{
    89				{"action": rx},
    90				{"entityType": rx},
    91				{"entityId": rx},
    92				{"actorId": rx},
    93				{"role": rx},
    94			}
    95		}
    96		total, err := app.Store.Audit.CountDocuments(ctx, filter)
    97		if err != nil {
    98			return nil, 0, err
    99		}
   100		sortDir := -1
   101		if q.Order == "oldest_first" {
   102			sortDir = 1
   103		}
   104		opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: sortDir}}).SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
   105		cur, err := app.Store.Audit.Find(ctx, filter, opts)
   106		if err != nil {
   107			return nil, 0, err
   108		}
   109		defer cur.Close(ctx)
   110		var entries []map[string]any
   111		for cur.Next(ctx) {
   112			var raw bson.M
   113			if err := cur.Decode(&raw); err != nil {
   114				continue
   115			}
   116			entries = append(entries, normalizeAudit(raw))
   117		}
   118		if entries == nil {
   119			entries = []map[string]any{}
   120		}
   121		_ = strings.TrimSpace
   122		return entries, int(total), nil
   123	}
