   125	func normalizeAudit(raw bson.M) map[string]any {
   126		str := func(keys ...string) string {
   127			for _, k := range keys {
   128				if v, ok := raw[k]; ok && v != nil {
   129					switch t := v.(type) {
   130					case string:
   131						return t
   132					}
   133				}
   134			}
   135			return ""
   136		}
   137		occurred := ""
   138		for _, k := range []string{"occurredAt", "occurred_at"} {
   139			if v, ok := raw[k]; ok {
   140				switch t := v.(type) {
   141				case time.Time:
   142					occurred = fmtTime(t)
   143				case bson.DateTime:
   144					occurred = fmtTime(t.Time())
   145				}
   146			}
   147		}
   148		success, _ := raw["success"].(bool)
   149		details := map[string]any{}
   150		if d, ok := raw["details"].(bson.M); ok {
   151			for k, v := range d {
   152				details[k] = v
   153			}
   154		} else if d, ok := raw["details"].(map[string]any); ok {
   155			details = d
   156		}
   157		id := str("auditId", "audit_id")
   158		actor := str("actorId", "actor_id")
   159		role := str("role", "actorRole")
   160		return map[string]any{
   161			"auditId":    id,
   162			"audit_id":   id,
   163			"actorId":    actor,
   164			"actor_id":   actor,
   165			"role":       role,
   166			"actorRole":  role,
   167			"action":     str("action"),
   168			"entityType": str("entityType", "entity_type"),
   169			"entity_type": str("entityType", "entity_type"),
   170			"entityId":   str("entityId", "entity_id"),
   171			"entity_id":  str("entityId", "entity_id"),
   172			"success":    success,
   173			"occurredAt": occurred,
   174			"occurred_at": occurred,
   175			"details":    details,
   176		}
   177	}
