   217	func hasCapacity(route *PlannedRoute, locByID map[uuid.UUID]Location, cooled bool) bool {
   218		for _, n := range route.Nodes {
   219			l := locByID[n]
   220			if cooled {
   221				if l.CooledCapacity > 0 && l.CooledCapacity-l.CooledReserved < 1 {
   222					return false
   223				}
   224			} else {
   225				if l.CapacityUnits > 0 && l.CapacityUnits-l.ReservedUnits < 1 {
   226					return false
   227				}
   228			}
   229		}
   230		// connections checked via hops if capacity configured
   231		return true
   232	}
