  1681	func (app *App) findAffectedJourneys(ctx context.Context, resourceType, resourceID string) []Journey {
  1682		samples, _ := app.Store.ListSamples(ctx)
  1683		seen := map[uuid.UUID]bool{}
  1684		var out []Journey
  1685		rid, _ := uuid.Parse(resourceID)
  1686		for _, sm := range samples {
  1687			if sm.ActiveJourneyID == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired {
  1688				continue
  1689			}
  1690			if seen[*sm.ActiveJourneyID] {
  1691				continue
  1692			}
  1693			hit := false
  1694			if resourceType == "worker" && sm.CurrentHolderID != nil && sm.CurrentHolderID.String() == resourceID {
  1695				hit = true
  1696			}
  1697			if (resourceType == "laboratory" || resourceType == "node" || resourceType == "location") && sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID == rid {
  1698				hit = true
  1699			}
  1700			asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
  1701			for _, a := range asgs {
  1702				if a.Status == StatusCompleted {
  1703					continue
  1704				}
  1705				if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
  1706					hit = true
  1707				}
  1708				if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
  1709					((a.NodeID != nil && *a.NodeID == rid) || (a.LaboratoryID != nil && *a.LaboratoryID == rid) ||
  1710						(a.FromLocationID != nil && *a.FromLocationID == rid) || (a.ToLocationID != nil && *a.ToLocationID == rid)) {
  1711					hit = true
  1712				}
  1713			}
  1714			if hit {
  1715				j, _ := app.Store.GetJourney(ctx, *sm.ActiveJourneyID)
  1716				if j != nil {
  1717					seen[j.ID] = true
  1718					out = append(out, *j)
  1719				}
  1720			}
  1721		}
  1722		sort.Slice(out, func(i, k int) bool { return out[i].ID.String() < out[k].ID.String() })
  1723		return out
  1724	}

