   618	func (s *Store) ReleaseReservationsForSample(ctx context.Context, sampleID uuid.UUID) error {
   619		rows, err := s.PG.Query(ctx, `SELECT id, resource_type, resource_id, cooled, units FROM capacity_reservations WHERE sample_id=$1 AND active=true`, sampleID)
   620		if err != nil {
   621			return err
   622		}
   623		defer rows.Close()
   624		type rec struct {
   625			id, resID uuid.UUID
   626			typ       string
   627			cooled    bool
   628			units     int
   629		}
   630		var recs []rec
   631		for rows.Next() {
   632			var r rec
   633			if err := rows.Scan(&r.id, &r.typ, &r.resID, &r.cooled, &r.units); err != nil {
   634				return err
   635			}
   636			recs = append(recs, r)
   637		}
   638		rows.Close()
   639		for _, r := range recs {
   640			col := "reserved_units"
   641			table := "locations"
   642			if r.typ == "connection" {
   643				table = "connections"
   644			}
   645			if r.cooled {
   646				col = "cooled_reserved_units"
   647			}
   648			if _, err := s.PG.Exec(ctx, fmt.Sprintf(`UPDATE %s SET %s = GREATEST(%s - $2, 0) WHERE id=$1`, table, col, col), r.resID, r.units); err != nil {
   649				return err
   650			}
   651			if _, err := s.PG.Exec(ctx, `UPDATE capacity_reservations SET active=false WHERE id=$1`, r.id); err != nil {
   652				return err
   653			}
   654		}
   655		return nil
   656	}
