  1714				if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
  1715					hit = true
  1716				}
  1717				if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
