    44		ver, _, _, _, _ := app.Store.CurrentSnapshot(ctx)
    45		res := ServiceabilityResult{Serviceable: false, Reason: "no_route", ServiceabilityVersion: ver}
    46	
    47		st, err := app.Store.GetSampleType(ctx, sampleTypeID)
    48		if err != nil {
    49			return res, err
    50		}
    51		if st == nil {
    52			res.Reason = "handling_rules_unsatisfiable"
