    73					cps = append(cps, l)
    74				}
    75			}
    76		} else {
    77			for _, l := range locs {
    78				if !l.Active || !l.Functions.CollectionPoint {
    79					continue
    80				}
    81				d := haversineKm(origin.Latitude, origin.Longitude, l.Latitude, l.Longitude)
    82				cov := l.CoverageKm
    83				if cov <= 0 {
    84					cov = 5
    85				}
    86				if cov > 5 {
    87					cov = 5
    88				}
    89				if d <= cov+1e-9 {
    90					cps = append(cps, l)
    91				}
    92			}
    93		}
    94		if len(cps) == 0 {
    95			res.Reason = "outside_service_coverage"
    96			return res, nil
    97		}
    98	
    99		// accepting labs
   100		var labs []Location
   101		for _, l := range locs {
   102			if !l.Active || !l.Functions.Laboratory {
   103				continue
   104			}
   105			ok, err := app.Store.LabAccepts(ctx, l.ID, sampleTypeID)
   106			if err != nil {
   107				return res, err
   108			}
   109			if ok {
   110				labs = append(labs, l)
   111			}
   112		}
   113		if len(labs) == 0 {
   114			res.Reason = "no_accepting_laboratory"
   115			return res, nil
   116		}
   117	
   118		// graph of active connections
   119		adj := map[uuid.UUID][]graphEdge{}
   120		locByID := map[uuid.UUID]Location{}
   121		for _, l := range locs {
   122			locByID[l.ID] = l
   123		}
   124		for _, c := range conns {
   125			if !c.Active {
   126				continue
   127			}
   128			from, ok1 := locByID[c.FromLocationID]
   129			to, ok2 := locByID[c.ToLocationID]
   130			if !ok1 || !ok2 || !from.Active || !to.Active {
   131				continue
   132			}
   133			if cooledRequired && !c.Cooled {
   134				continue
   135			}
   136			adj[c.FromLocationID] = append(adj[c.FromLocationID], graphEdge{to: c.ToLocationID, conn: c})
   137		}
   138	
   139		best := (*PlannedRoute)(nil)
   140		bestScore := math.MaxFloat64
   141	
   142		for _, cp := range cps {
   143			for _, lab := range labs {
   144				route := dijkstra(cp.ID, lab.ID, adj, locByID)
   145				if route == nil {
   146					// same node can be both collection and lab
   147					if cp.ID == lab.ID {
   148						route = &PlannedRoute{
   149							CollectionPoint: cp.ID,
   150							Laboratory:      lab.ID,
   151							Nodes:           []uuid.UUID{cp.ID},
   152							NeedsCooled:     cooledRequired,
   153						}
   154					} else {
   155						continue
   156					}
   157				}
   158				// capacity check along path
   159				if !hasCapacity(route, locByID, cooledRequired) {
   160					if best == nil {
   161						res.Reason = "insufficient_capacity"
   162					}
   163					continue
   164				}
   165				// travel time from origin to CP
   166				toCP := 0
   167				if originType != OriginNode || originNodeID == nil || *originNodeID != cp.ID {
   168					d := haversineKm(origin.Latitude, origin.Longitude, locByID[cp.ID].Latitude, locByID[cp.ID].Longitude)
   169					toCP = int(math.Ceil(d / 0.4)) // ~24 km/h
   170					if toCP < 5 {
   171						toCP = 5
   172					}
   173				}
   174				handling := locByID[cp.ID].HandlingMinutes
   175				for _, n := range route.Nodes {
   176					if n == cp.ID {
   177						continue
   178					}
   179					handling += locByID[n].HandlingMinutes
   180				}
   181				total := toCP + handling + route.TotalMinutes
   182				eta := requestedAt.Add(time.Duration(total) * time.Minute)
   183				if earliest.After(requestedAt) {
   184					eta = earliest.Add(time.Duration(total) * time.Minute)
   185				}
   186				if eta.After(deadline) {
   187					if best == nil && res.Reason != "insufficient_capacity" {
   188						res.Reason = "deadline_unreachable"
   189					}
   190					continue
   191				}
   192				score := float64(total) + route.TotalCost
   193				if score < bestScore {
   194					bestScore = score
   195					cpCopy := cp
   196					labID := lab.ID
   197					r := *route
   198					r.CollectionPoint = cp.ID
   199					r.Laboratory = lab.ID
   200					r.NeedsCooled = cooledRequired

