   284			if _, err := s.PG.Exec(ctx, `INSERT INTO certifications (id, user_id, code, active, expires_at) VALUES ($1,$2,$3,$4,$5)`,
   285				uuid.New(), userID, c.Code, c.Active, exp); err != nil {
