   239	func dijkstra(src, dst uuid.UUID, adj map[uuid.UUID][]graphEdge, locByID map[uuid.UUID]Location) *PlannedRoute {
   240		type item struct {
   241			id    uuid.UUID
   242			cost  float64
   243			mins  int
   244			prev  uuid.UUID
   245			via   *Connection
   246			hasP  bool
   247		}
   248		dist := map[uuid.UUID]float64{src: 0}
   249		prev := map[uuid.UUID]uuid.UUID{}
   250		via := map[uuid.UUID]Connection{}
   251		mins := map[uuid.UUID]int{src: 0}
   252		visited := map[uuid.UUID]bool{}
   253	
   254		for {
   255			var best uuid.UUID
   256			bestC := math.MaxFloat64
   257			found := false
   258			for id, c := range dist {
   259				if visited[id] {
   260					continue
   261				}
   262				if c < bestC {
   263					bestC = c
   264					best = id
   265					found = true
   266				}
   267			}
   268			if !found {
   269				break
   270			}
   271			if best == dst {
   272				break
   273			}
   274			visited[best] = true
   275			for _, e := range adj[best] {
   276				nc := bestC + e.conn.CostUnits + float64(e.conn.TravelMinutes)*0.01
   277				old, ok := dist[e.to]
   278				if !ok || nc < old {
   279					dist[e.to] = nc
   280					prev[e.to] = best
   281					via[e.to] = e.conn
   282					mins[e.to] = mins[best] + e.conn.TravelMinutes
   283				}
   284			}
   285		}
   286		if _, ok := dist[dst]; !ok && src != dst {
   287			return nil
   288		}
   289		if src == dst {
   290			return &PlannedRoute{CollectionPoint: src, Laboratory: dst, Nodes: []uuid.UUID{src}}
   291		}
   292		var hops []RouteHop
   293		var nodes []uuid.UUID
   294		cur := dst
   295		for cur != src {
   296			p, ok := prev[cur]
   297			if !ok {
   298				return nil
   299			}
   300			c := via[cur]
   301			hops = append([]RouteHop{{From: p, To: cur, ConnectionID: c.ID, Minutes: c.TravelMinutes, Cost: c.CostUnits, Cooled: c.Cooled}}, hops...)
   302			nodes = append([]uuid.UUID{cur}, nodes...)
   303			cur = p
   304		}
   305		nodes = append([]uuid.UUID{src}, nodes...)
   306		totalM, totalC := 0, 0.0
   307		for _, h := range hops {
   308			totalM += h.Minutes
   309			totalC += h.Cost
   310		}
   311		return &PlannedRoute{CollectionPoint: src, Laboratory: dst, Hops: hops, Nodes: nodes, TotalMinutes: totalM, TotalCost: totalC}
   312	}
