    82				cov := l.CoverageKm
    83				if cov <= 0 {
    84					cov = 5
    85				}
    86				if cov > 5 {
    87					cov = 5
    88				}
    89				if d <= cov+1e-9 {
    90					cps = append(cps, l)
    91				}
    92			}
    93		}
