   499		if err := app.Store.UpdateSample(ctx, *sm); err != nil {
   500			return nil, nil, err
   501		}
   502	
   503		_, _ = app.Store.AddTimeline(ctx, "journey_created", actorID, role, "sample", sm.ID.String(), true, map[string]interface{}{
   504			"journeyId": jid.String(),
   505		})
   506		_, _ = app.Store.AddRealtime(ctx, "journey.created", "journey", jid.String(), map[string]interface{}{"sampleId": sm.ID.String()})
   507		return &j, asgs, nil
   508	}
   509	
   510	func (app *App) offerNext(ctx context.Context, sm *Sample, asgs []Assignment, st *SampleType) error {
   511		// find first pending assignment that is ready (prior completed or first)
   512		sort.Slice(asgs, func(i, j int) bool { return asgs[i].Sequence < asgs[j].Sequence })
   513		for i := range asgs {
   514			a := &asgs[i]
   515			if a.Status != StatusPending {
   516				continue
   517			}
   518			// skip if already offered and not expired
   519			if a.OfferedTo != nil && a.OfferExpiresAt != nil && a.OfferExpiresAt.After(time.Now()) {
   520				return nil
   521			}
   522			// prior must be completed or accepted for collection? collection can start first
   523			if i > 0 {
   524				prevDone := asgs[i-1].Status == StatusCompleted
   525				// allow offering next after previous accepted for pipeline, but typically after complete
   526				if !prevDone && asgs[i-1].Status != StatusAccepted && asgs[i-1].Status != StatusInProgress {
   527					// still offer collection first only
   528					if a.Kind != KindCollection {
   529						continue
   530					}
   531				}
   532			}
   533			worker, err := app.pickWorker(ctx, *a, st)
   534			if err != nil {
   535				return err
   536			}
   537			if worker == nil {
   538				// leave pending unoffered; exception later
   539				return nil
   540			}
   541			exp := time.Now().UTC().Add(OfferTimeout)
   542			a.OfferedTo = &worker.ID
   543			a.OfferExpiresAt = &exp
   544			if err := app.Store.UpdateAssignment(ctx, *a); err != nil {
   545				return err
   546			}
   547			_ = app.Store.MarkOffered(ctx, worker.ID)
   548			_, _ = app.Store.AddTimeline(ctx, "assignment_offered", "system", "system", "assignment", a.ID.String(), true, map[string]interface{}{
   549				"workerId": worker.ID.String(), "kind": a.Kind,
   550			})
   551			_, _ = app.Store.AddRealtime(ctx, "assignment.offered", "assignment", a.ID.String(), map[string]interface{}{
   552				"workerId": worker.ID.String(),
   553			})
   554			if sm.Status == StatusRequested {
   555				sm.Status = StatusOffered
   556				_ = app.Store.UpdateSample(ctx, *sm)
   557			}
   558			return nil
   559		}
   560		return nil
   561	}
   562	
   563	func (app *App) pickWorker(ctx context.Context, a Assignment, st *SampleType) (*User, error) {
   564		users, err := app.Store.ListUsers(ctx)
   565		if err != nil {
   566			return nil, err
   567		}
   568		type cand struct {
   569			u     User
   570			load  int
   571			score int
   572		}
   573		var cs []cand
   574		now := time.Now().UTC()
   575		for _, u := range users {
   576			if !u.Active || !u.Available {
   577				continue
   578			}
   579			switch a.Kind {
   580			case KindCollection:
   581				if !containsString(u.Roles, RoleCollectionProfessional) {
   582					continue
   583				}
   584				if st != nil && st.QualifiedCollectorRequired {
   585					ok := false
   586					certs, _ := app.Store.GetCertifications(ctx, u.ID)
   587					for _, c := range certs {
   588						if c.Active && c.Code == st.RequiredQualification {
   589							if c.ExpiresAt == nil || *c.ExpiresAt == "" {
   590								ok = true
   591								break
   592							}
   593							t, err := time.Parse(time.RFC3339, *c.ExpiresAt)
   594							if err == nil && t.After(now) {
   595								ok = true
   596								break
   597							}
   598						}
   599					}
   600					if !ok && containsString(u.Qualifications, st.RequiredQualification) {
   601						ok = true
   602					}
   603					if !ok {
   604						continue
   605					}
   606				}
   607			case KindTransport:
   608				if !containsString(u.Roles, RoleDeliveryPartner) {
   609					continue
   610				}
   611			case KindNode:
   612				if !containsString(u.Roles, RoleNodeHandler) {
   613					continue
   614				}
   615				if a.NodeID != nil && (u.AssignedLocationID == nil || *u.AssignedLocationID != *a.NodeID) {
   616					continue
   617				}
   618			case KindLaboratory:
   619				if !containsString(u.Roles, RoleLaboratoryTeam) {
   620					continue
   621				}
   622				if a.LaboratoryID != nil && (u.AssignedLocationID == nil || *u.AssignedLocationID != *a.LaboratoryID) {
   623					continue
   624				}
   625			default:
   626				continue
   627			}
   628			asgs, _ := app.Store.ListAssignmentsForWorker(ctx, u.ID)
   629			load := 0
   630			for _, x := range asgs {
   631				if x.Status == StatusAccepted || x.Status == StatusInProgress || x.Status == StatusPending {
   632					load++
   633				}
   634			}
   635			score := load * 10
   636			if u.DeclineWindowStart != nil && now.Sub(*u.DeclineWindowStart) < DeclinePenalty {
   637				score += u.DeclineCount * 5
   638			}
   639			if u.LastOfferedAt != nil {
   640				// prefer those not recently offered
   641				mins := int(now.Sub(*u.LastOfferedAt).Minutes())
   642				if mins < 30 {
   643					score += (30 - mins)
   644				}
   645			}
   646			cs = append(cs, cand{u: u, load: load, score: score})
   647		}
   648		if len(cs) == 0 {
   649			return nil, nil
   650		}
   651		sort.Slice(cs, func(i, j int) bool {
   652			if cs[i].score != cs[j].score {
   653				return cs[i].score < cs[j].score
   654			}
   655			return cs[i].u.Username < cs[j].u.Username
   656		})
   657		return &cs[0].u, nil
   658	}
   659	
   660	func (app *App) rebuildServiceabilitySnapshot(ctx context.Context) {
   661		app.snapMu.Lock()
   662		defer app.snapMu.Unlock()
   663		locs, err := app.Store.ListLocations(ctx)
   664		if err != nil {
   665			return
   666		}
   667		type region struct {
   668			LocationID string  `json:"locationId"`
   669			Name       string  `json:"name"`
   670			Latitude   float64 `json:"latitude"`
   671			Longitude  float64 `json:"longitude"`
   672			CoverageKm float64 `json:"coverageKm"`
   673		}
   674		var regions []region
   675		count := 0
   676		for _, l := range locs {
   677			if l.Active && l.Functions.CollectionPoint {
   678				cov := l.CoverageKm
   679				if cov <= 0 {
   680					cov = 5
   681				}
   682				if cov > 5 {
   683					cov = 5
   684				}
   685				regions = append(regions, region{
   686					LocationID: l.ID.String(), Name: l.Name,
   687					Latitude: l.Latitude, Longitude: l.Longitude, CoverageKm: cov,
   688				})
   689				count++
   690			}
   691		}
   692		if regions == nil {
   693			regions = []region{}
   694		}
   695		payload, _ := jsonMarshal(map[string]any{"regions": regions, "activeCollectionPointCount": count})
   696		rev, _ := app.Store.NetworkRevision(ctx)
   697		ver, _ := app.Store.NextServiceabilityVersion(ctx)
   698		_ = app.Store.PublishSnapshot(ctx, ver, rev, payload)
   699	}
   700	
   701	func jsonMarshal(v any) ([]byte, error) {
   702		return json.Marshal(v)
   703	}

