   457	func parseFunctions(fns []string) (LocationFunctions, bool) {
   458		var f LocationFunctions
   459		for _, x := range fns {
   460			switch x {
   461			case FnCollectionPoint:
   462				f.CollectionPoint = true
   463			case FnTransferPoint:
   464				f.TransferPoint = true
   465			case FnHub:
   466				f.Hub = true
   467			case FnLaboratory:
   468				f.Laboratory = true
   469			default:
   470				return f, false
   471			}
   472		}
   473		return f, true
   474	}
