   808	func (app *App) sampleStatePayload(ctx context.Context, sm Sample, auth *AuthContext) map[string]any {
   809		now := time.Now().UTC()
   810		hist, _ := app.Store.ListTimeline(ctx, "sample", sm.ID.String())
   811		asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
   812		var legs []map[string]any
   813		for _, a := range asgs {
   814			if a.Kind == KindTransport || a.Kind == KindCollection {
   815				m := map[string]any{
   816					"assignmentId": a.ID.String(),
   817					"kind":         a.Kind,
   818					"status":       a.Status,
   819				}
   820				if a.FromLocationID != nil {
   821					m["fromLocationId"] = a.FromLocationID.String()
   822				}
   823				if a.ToLocationID != nil {
   824					m["toLocationId"] = a.ToLocationID.String()
   825				}
   826				if a.WorkerID != nil {
   827					m["workerId"] = a.WorkerID.String()
   828				}
   829				legs = append(legs, m)
   830			}
   831		}
   832		if legs == nil {
   833			legs = []map[string]any{}
   834		}
   835		stale := sm.LocationStale(now)
   836		out := map[string]any{
   837			"sampleId":               sm.ID.String(),
   838			"requestId":              sm.RequestID.String(),
   839			"status":                 sm.Status,
   840			"sealed":                 sm.Sealed,
   841			"serviceability":         sm.Serviceability,
   842			"serviceabilityReason":   sm.ServiceabilityReason,
   843			"deliveryDeadline":       fmtTime(sm.DeliveryDeadline),
   844			"earliestCollectionAt":   fmtTime(sm.EarliestCollectionAt),
   845			"latestCollectionAt":     fmtTime(sm.LatestCollectionAt),
   846			"originType":             sm.OriginType,
   847			"sampleTypeId":           sm.SampleTypeID.String(),
   848			"locationStale":          stale,
   849			"freshness":              map[string]any{"stale": stale, "lastUpdatedAt": fmtTimePtr(sm.LocationRecordedAt)},
   850			"history":                hist,
   851			"timeline":               hist,
   852			"legs":                   legs,
   853			"alreadySealed":          sm.AlreadySealed,
   854		}
   855		if sm.CurrentHolderID != nil {
   856			out["currentHolderId"] = sm.CurrentHolderID.String()
   857			out["currentCustodianId"] = sm.CurrentHolderID.String()
   858			if u, _ := app.Store.GetUserByID(ctx, *sm.CurrentHolderID); u != nil {
   859				out["currentCustodian"] = u.FullName
   860				if u.FullName == "" {
   861					out["currentCustodian"] = u.Username
   862				}
   863			}
   864		}
   865		if sm.LatestLat != nil && sm.LatestLng != nil {
   866			out["latestLocation"] = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
   867			out["currentLocation"] = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
   868		}
   869		if sm.LocationRecordedAt != nil {
   870			out["lastLocationAt"] = fmtTime(*sm.LocationRecordedAt)
   871			out["lastUpdatedAt"] = fmtTime(*sm.LocationRecordedAt)
   872		}
   873		if sm.ActiveJourneyID != nil {
   874			out["journeyId"] = sm.ActiveJourneyID.String()
   875			stops, _ := app.Store.ListStops(ctx, *sm.ActiveJourneyID)
   876			done := 0
   877			for _, st := range stops {
   878				if st.CompletedAt != nil {
   879					done++
   880				}
   881			}
   882			out["routeProgress"] = map[string]any{"completedStops": done, "totalStops": len(stops)}
   883		}
   884		if sm.TargetLaboratoryID != nil {
   885			out["targetLaboratoryId"] = sm.TargetLaboratoryID.String()
   886		}
   887		if sm.Exception != nil {
   888			out["exception"] = sm.Exception
   889		}
   890		if sm.SealedAt != nil {
   891			out["sealedAt"] = fmtTime(*sm.SealedAt)
   892		}
   893		// hide extra details for relay courier — only their assigned leg
   894		if auth != nil && requireRole(auth, RoleDeliveryPartner) && !requireRole(auth, RoleAdministrator, RoleDispatcher) {
   895			// already limited
   896		}
   897		return out
   898	}
