import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec=json.load(f)

# dump 200 responses for remaining ops
for path, methods in spec['paths'].items():
    for method, op in methods.items():
        if method not in ('get','post','put','patch','delete'):
            continue
        r200 = op.get('responses',{}).get('200') or op.get('responses',{}).get('201')
        if not r200:
            continue
        schema = r200.get('content',{}).get('application/json',{}).get('schema',{})
        data = schema.get('properties',{}).get('data',{})
        print(f'\n======== {op.get("operationId")} {method.upper()} {path} ========')
        print('status', '200' if '200' in op['responses'] else '201')
        print(json.dumps(data, indent=2)[:1800])

print('\n\n======== error codes by path ========')
for path, methods in spec['paths'].items():
    for method, op in methods.items():
        if method not in ('get','post','put','patch','delete'):
            continue
        codes = {}
        for code, resp in op.get('responses',{}).items():
            if code.startswith('2'):
                continue
            sch = resp.get('content',{}).get('application/json',{}).get('schema',{})
            enum = sch.get('properties',{}).get('code',{}).get('enum')
            codes[code] = enum
        if codes:
            print(op.get('operationId'), codes)
