   136	func (app *App) expireAndReoffer(ctx context.Context) {
   137		asgs, err := app.Store.ListOpenOffered(ctx)
   138		if err != nil {
   139			return
   140		}
   141		now := time.Now().UTC()
   142		for _, a := range asgs {
   143			if a.OfferExpiresAt != nil && now.After(*a.OfferExpiresAt) {
   144				if a.OfferedTo != nil {
   145					_ = app.Store.BumpDecline(ctx, *a.OfferedTo)
   146				}
   147				a.OfferedTo = nil
   148				a.OfferExpiresAt = nil
   149				_ = app.Store.UpdateAssignment(ctx, a)
   150				sm, _ := app.Store.GetSample(ctx, a.SampleID)
   151				if sm == nil {
   152					continue
   153				}
   154				st, _ := app.Store.GetSampleType(ctx, sm.SampleTypeID)
   155				all, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
   156				_ = app.offerNext(ctx, sm, all, st)
   157				// if still no worker after long time, exception
   158				if sm.CreatedAtZero() {
   159					continue
   160				}
   161			}
   162		}
   163		// flag samples with unoffered required assignments for too long
   164		samples, _ := app.Store.ListSamples(ctx)
   165		for _, sm := range samples {
   166			if sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired || sm.Status == StatusException || sm.Status == StatusUnserviceable {
   167				continue
   168			}
   169			asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
   170			for _, a := range asgs {
   171				if a.Status == StatusPending && a.OfferedTo == nil && a.Kind == KindCollection {
   172					// created long ago?
   173					st, _ := app.Store.GetSampleType(ctx, sm.SampleTypeID)
   174					if st != nil && st.QualifiedCollectorRequired {
   175						// try offer again
   176						_ = app.offerNext(ctx, &sm, asgs, st)
   177						// if still none, check age via first timeline? use requested_at
   178						if time.Since(sm.RequestedAt) > NoWorkerTimeout {
   179							sm.Status = StatusException
   180							sm.Exception = map[string]interface{}{"reason": "no_qualified_worker", "assignmentId": a.ID.String()}
   181							_ = app.Store.UpdateSample(ctx, sm)
   182							app.writeAudit(ctx, "system", "system", "exception", "sample", sm.ID.String(), true, sm.Exception)
   183						}
   184					}
   185				}
   186			}
   187		}
   188	}
