   394			IdempotencyKey string `json:"idempotencyKey"`
   395		}
   396		if err := decodeJSON(r, &req); err != nil {
   397			writeErr(w, 400, "invalid_json", "invalid json")
   398			return
   399		}
   400		sid, err := uuid.Parse(req.SampleID)
