   417			writeErr(w, 404, "not_found", "sample")
   418			return
   419		}
   420		if sm.Status == StatusReceived {
   421			writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status})
   422			return
   423		}
   424		if at.After(sm.DeliveryDeadline) {
   425			// still receive but mark expired? Spec: if received after deadline it's still received; expired is if no valid route
   426		}
   427		sm.Status = StatusReceived
   428		sm.ReceivedLaboratoryID = &lid
   429		sm.ReceivedAt = &at
   430		sm.CurrentHolderID = &auth.User.ID
   431		sm.LocationRecordedAt = &at
   432		_ = app.Store.UpdateSample(r.Context(), *sm)
   433		_ = app.Store.ReleaseReservationsForSample(r.Context(), sm.ID)
   434		if sm.ActiveJourneyID != nil {
