   439			}
   440		}
   441		asgs, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
   442		now := time.Now().UTC()
   443		for _, a := range asgs {
   444			if a.Kind == KindLaboratory && (a.Status == StatusAccepted || a.Status == StatusInProgress || a.Status == StatusPending) {
   445				a.Status = StatusCompleted
   446				a.CompletedAt = &now
   447				if a.WorkerID == nil {
   448					a.WorkerID = &auth.User.ID
   449				}
   450				_ = app.Store.UpdateAssignment(r.Context(), a)
   451			}
   452		}
   453		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "confirm_laboratory_receipt", "sample", sm.ID.String(), true, nil)
   454		_, _ = app.Store.AddRealtime(r.Context(), "sample.received", "sample", sm.ID.String(), nil)
