  1483		if sm == nil {
  1484			writeErr(w, 404, "not_found", "sample")
  1485			return
  1486		}
  1487		// preserve holder and completed work
  1488		holder := sm.CurrentHolderID
  1489		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
