  1501			writeErr(w, 500, "internal_error", "compute")
  1502			return
  1503		}
  1504		j.PlanVersion++
  1505		if !res.Serviceable {
  1506			j.Valid = false
  1507			rs := "expired"
  1508			j.ReplanStatus = &rs
  1509			sm.Status = StatusExpired
  1510			sm.Serviceability = "unserviceable"
  1511			sm.ServiceabilityReason = res.Reason
  1512			sm.CurrentHolderID = holder
