   267	func (s *Store) ReplaceCertifications(ctx context.Context, userID uuid.UUID, certs []Certification) error {
   268		if _, err := s.PG.Exec(ctx, `DELETE FROM certifications WHERE user_id=$1`, userID); err != nil {
