   272			var exp *time.Time
   273			if c.ExpiresAt != nil && *c.ExpiresAt != "" {
   274				t, err := time.Parse(time.RFC3339, *c.ExpiresAt)
   275				if err != nil {
   276					t2, err2 := time.Parse(time.RFC3339Nano, *c.ExpiresAt)
   277					if err2 != nil {
   278						return fmt.Errorf("invalid certification expiry")
   279					}
   280					t = t2
   281				}
   282				exp = &t
   283			}
   284			if _, err := s.PG.Exec(ctx, `INSERT INTO certifications (id, user_id, code, active, expires_at) VALUES ($1,$2,$3,$4,$5)`,
   285				uuid.New(), userID, c.Code, c.Active, exp); err != nil {
   286				return err
   287			}
   288		}
   289		return nil
   290	}
