  1629	func (app *App) handleMerge(w http.ResponseWriter, r *http.Request) {
  1630		auth := getAuth(r)
  1631		if !roleSelected(auth) {
  1632			writeErr(w, 409, "role_not_selected", "select a role")
  1633			return
  1634		}
  1635		if !adminOrDispatcher(auth) {
  1636			writeErr(w, 403, "forbidden", "forbidden")
  1637			return
  1638		}
  1639		var req struct {
  1640			JourneyIDs          []string `json:"journeyIds"`
  1641			ExpectedPlanVersions []int   `json:"expectedPlanVersions"`
  1642			IdempotencyKey      string   `json:"idempotencyKey"`
  1643		}
  1644		if err := decodeJSON(r, &req); err != nil {
  1645			writeErr(w, 400, "invalid_json", "invalid json")
  1646			return
  1647		}
  1648		if len(req.JourneyIDs) < 2 {
  1649			writeErr(w, 400, "invalid_json", "need at least two journeys")
  1650			return
  1651		}
  1652		var journeys []Journey
  1653		var samples []Sample
  1654		for i, js := range req.JourneyIDs {
  1655			id, err := uuid.Parse(js)
  1656			if err != nil {
  1657				writeErr(w, 404, "not_found", "not found")
  1658				return
  1659			}
  1660			j, _ := app.Store.GetJourney(r.Context(), id)
  1661			if j == nil {
  1662				writeErr(w, 404, "not_found", "not found")
  1663				return
  1664			}
  1665			if i < len(req.ExpectedPlanVersions) && req.ExpectedPlanVersions[i] != j.PlanVersion {
  1666				writeErr(w, 409, "stale_plan", "stale plan")
  1667				return
  1668			}
  1669			journeys = append(journeys, *j)
  1670			sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
  1671			for _, sid := range sids {
  1672				sm, _ := app.Store.GetSample(r.Context(), sid)
  1673				if sm != nil {
  1674					samples = append(samples, *sm)
  1675				}
  1676			}
  1677		}
  1678		// compatibility
  1679		if !compatibleBatch(samples) {
  1680			writeErr(w, 409, "incompatible_batch", "samples cannot travel together")
