  1705	func compatibleBatch(samples []Sample) bool {
  1706		for i, a := range samples {
  1707			stA, _ := (*App)(nil).unused()
  1708			_ = stA
  1709			if false {
  1710				_ = i
  1711			}
  1712			for j, b := range samples {
  1713				if i == j {
  1714					continue
  1715				}
  1716				for _, inc := range a.IncompatibleSampleTypes {
  1717					if inc == b.SampleTypeID {
  1718						return false
  1719					}
  1720				}
  1721				// Pulse must not wait to be batched
  1722				// check names via type id known defaults
  1723				if a.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" ||
  1724					b.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" {
  1725					return false
  1726				}
  1727				// temperature overlap
  1728				if a.TemperatureMaxC < b.TemperatureMinC || b.TemperatureMaxC < a.TemperatureMinC {
  1729					return false
  1730				}
  1731			}
  1732		}
  1733		return true
  1734	}
