   194	func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
   195		const R = 6371.0
   196		toRad := func(d float64) float64 { return d * 3.141592653589793 / 180 }
   197		dLat := toRad(lat2 - lat1)
   198		dLng := toRad(lng2 - lng1)
   199		a := sin(dLat/2)*sin(dLat/2) + cos(toRad(lat1))*cos(toRad(lat2))*sin(dLng/2)*sin(dLng/2)
   200		return 2 * R * asin(minF(1, sqrt(a)))
   201	}
   202	
   203	func sin(x float64) float64  { return math.Sin(x) }
   204	func cos(x float64) float64  { return math.Cos(x) }
   205	func asin(x float64) float64 { return math.Asin(x) }
   206	func sqrt(x float64) float64 { return math.Sqrt(x) }
   207	func minF(a, b float64) float64 {
   208		if a < b {
   209			return a
   210		}
   211		return b
   212	}
