   303			IdempotencyKey string `json:"idempotencyKey"`
   304		}
   305		if err := decodeJSON(r, &req); err != nil {
   306			writeErr(w, 400, "invalid_json", "invalid json")
   307			return
   308		}
   309		if req.Party != "sender" && req.Party != "receiver" {
   310			writeErr(w, 400, "invalid_json", "invalid party")
   311			return
   312		}
   313		hid, err := uuid.Parse(req.HandoffID)
   314		if err != nil {
   315			writeErr(w, 404, "not_found", "not found")
   316			return
   317		}
   318		h, _ := app.Store.GetHandoff(r.Context(), hid)
   319		if h == nil {
   320			writeErr(w, 404, "not_found", "not found")
   321			return
   322		}
   323		if h.Status == "confirmed" {
   324			writeData(w, 200, handoffPayload(*h))
   325			return
   326		}
   327		if req.Party == "sender" {
   328			if h.SenderID != auth.User.ID {
   329				writeErr(w, 403, "forbidden", "not sender")
   330				return
   331			}
   332			h.SenderConfirmed = true
   333		} else {
   334			if h.ReceiverID != auth.User.ID {
   335				writeErr(w, 403, "forbidden", "not receiver")
   336				return
   337			}
   338			h.ReceiverConfirmed = true
   339		}
   340		if h.SenderConfirmed && h.ReceiverConfirmed {
   341			now := time.Now().UTC()
   342			h.Status = "confirmed"
   343			h.ConfirmedAt = &now
   344			sm, _ := app.Store.GetSample(r.Context(), h.SampleID)
   345			if sm != nil {
   346				sm.CurrentHolderID = &h.ReceiverID
   347				sm.PendingHandoffID = nil
   348				from, _ := app.Store.GetAssignment(r.Context(), h.FromAssignmentID)
   349				to, _ := app.Store.GetAssignment(r.Context(), h.ToAssignmentID)
   350				if from != nil && from.Status != StatusCompleted {
   351					from.Status = StatusCompleted
   352					from.CompletedAt = &now
   353					_ = app.Store.UpdateAssignment(r.Context(), *from)
   354				}
   355				if to != nil && to.Status == StatusAccepted {
   356					to.Status = StatusInProgress
   357					_ = app.Store.UpdateAssignment(r.Context(), *to)
   358				}
   359				if to != nil {
   360					switch to.Kind {
