   151	func (app *App) withIdempotency(endpoint string, next http.HandlerFunc) http.HandlerFunc {
   152		return func(w http.ResponseWriter, r *http.Request) {
   153			auth := getAuth(r)
   154			body, err := io.ReadAll(r.Body)
   155			if err != nil {
   156				writeErr(w, 400, "invalid_json", "invalid json")
   157				return
   158			}
   159			r.Body = io.NopCloser(strings.NewReader(string(body)))
   160	
   161			var peek map[string]any
   162			_ = json.Unmarshal(body, &peek)
   163			key, _ := peek["idempotencyKey"].(string)
   164			if key == "" {
   165				writeErr(w, 400, "idempotency_required", "idempotencyKey is required")
   166				return
   167			}
   168			h := hashBytes(body)
   169			if auth != nil {
   170				storedHash, status, storedBody, ok, err := app.Store.GetIdempotency(r.Context(), key, auth.User.ID, endpoint)
   171				if err == nil && ok {
   172					if storedHash != h {
   173						writeErr(w, 409, "idempotency_conflict", "idempotency key reused with different request")
   174						return
   175					}
   176					w.Header().Set("Content-Type", "application/json")
   177					w.WriteHeader(status)
   178					_, _ = w.Write(storedBody)
   179					return
   180				}
   181			}
   182			cw := &captured{ResponseWriter: w, status: 200}
   183			next(cw, r)
   184			if auth != nil && cw.status < 500 {
   185				_ = app.Store.PutIdempotency(r.Context(), key, auth.User.ID, endpoint, h, cw.status, cw.buf)
   186			}
   187		}
   188	}
