   705	func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
   706		auth := getAuth(r)
   707		if !roleSelected(auth) {
   708			writeErr(w, 409, "role_not_selected", "select a role")
   709			return
   710		}
   711		var req struct {
   712			Role string `json:"role"`
   713		}
   714		_ = json.NewDecoder(r.Body).Decode(&req)
   715		role := auth.ActiveRole
   716		if req.Role != "" {
   717			if req.Role != auth.ActiveRole {
   718				writeErr(w, 403, "forbidden", "role must match active role")
   719				return
   720			}
   721			role = req.Role
   722		}
   723		now := time.Now().UTC()
   724		var pending, inProg, completed []map[string]any
   725	
   726		switch role {
   727		case RoleRequester:
   728			samples, _ := app.Store.ListSamplesByRequester(r.Context(), auth.User.ID)
   729			for _, sm := range samples {
   730				item := app.sampleWorkItem(r.Context(), sm, now)
   731				switch {
   732				case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
   733					completed = append(completed, item)
   734				case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
   735					pending = append(pending, item)
   736				default:
   737					inProg = append(inProg, item)
   738				}
   739			}
   740		case RoleAdministrator, RoleDispatcher:
   741			samples, _ := app.Store.ListSamples(r.Context())
   742			for _, sm := range samples {
   743				item := app.sampleWorkItem(r.Context(), sm, now)
   744				switch {
   745				case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
   746					completed = append(completed, item)
   747				case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
   748					pending = append(pending, item)
   749				default:
   750					inProg = append(inProg, item)
   751				}
   752			}
   753		default:
   754			asgs, _ := app.Store.ListAssignmentsForWorker(r.Context(), auth.User.ID)
   755			for _, a := range asgs {
   756				// filter by role kind
   757				if !assignmentMatchesRole(a.Kind, role) {
   758					continue
   759				}
   760				item := app.assignmentWorkItem(r.Context(), a)
   761				switch a.Status {
   762				case StatusCompleted, StatusCancelled:
   763					completed = append(completed, item)
   764				case StatusAccepted, StatusInProgress:
   765					inProg = append(inProg, item)
   766				default:
   767					pending = append(pending, item)
   768				}
   769			}
   770		}
   771		if pending == nil {
   772			pending = []map[string]any{}
   773		}
   774		if inProg == nil {
   775			inProg = []map[string]any{}
   776		}
   777		if completed == nil {
   778			completed = []map[string]any{}
   779		}
   780		writeData(w, 200, map[string]any{
   781			"role":              role,
   782			"pending":           pending,
   783			"inProgress":        inProg,
   784			"completed":         completed,
   785			"current":           append(append([]map[string]any{}, pending...), inProg...),
   786			"past":              completed,
   787		})
   788	}
