    13	func (app *App) handleAccept(w http.ResponseWriter, r *http.Request) {
    14		auth := getAuth(r)
    15		if !roleSelected(auth) {
    16			writeErr(w, 409, "role_not_selected", "select a role")
    17			return
    18		}
    19		var req struct {
    20			AssignmentID   string `json:"assignmentId"`
    21			IdempotencyKey string `json:"idempotencyKey"`
    22		}
    23		if err := decodeJSON(r, &req); err != nil {
    24			writeErr(w, 400, "invalid_json", "invalid json")
    25			return
    26		}
    27		aid, err := uuid.Parse(req.AssignmentID)
    28		if err != nil {
    29			writeErr(w, 404, "not_found", "not found")
    30			return
    31		}
    32		a, _ := app.Store.GetAssignment(r.Context(), aid)
    33		if a == nil {
    34			writeErr(w, 404, "not_found", "not found")
    35			return
    36		}
    37		if a.OfferedTo == nil || *a.OfferedTo != auth.User.ID {
    38			writeErr(w, 409, "assignment_not_offered", "not offered to this worker")
    39			return
    40		}
    41		if a.Status != StatusPending {
    42			writeErr(w, 409, "assignment_not_offered", "not pending")
    43			return
    44		}
    45		now := time.Now().UTC()
    46		a.Status = StatusAccepted
    47		a.WorkerID = &auth.User.ID
    48		a.AcceptedAt = &now
    49		if err := app.Store.UpdateAssignment(r.Context(), *a); err != nil {
    50			writeErr(w, 500, "internal_error", "update")
    51			return
    52		}
    53		sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
    54		if sm != nil {
    55			if sm.Status == StatusOffered || sm.Status == StatusRequested {
    56				sm.Status = StatusAccepted
    57				_ = app.Store.UpdateSample(r.Context(), *sm)
    58			}
    59			j, _ := app.Store.GetJourney(r.Context(), a.JourneyID)
    60			if j != nil && j.Status == StatusPlanned {
    61				j.Status = StatusActive
    62				_ = app.Store.UpdateJourney(r.Context(), *j)
    63			}
    64		}
    65		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "accept_assignment", "assignment", a.ID.String(), true, nil)
    66		_, _ = app.Store.AddRealtime(r.Context(), "assignment.accepted", "assignment", a.ID.String(), nil)
    67		writeData(w, 200, map[string]any{"assignmentId": a.ID.String(), "status": a.Status})
    68	}
