    24	
    25	func Connect(ctx context.Context) (*Store, error) {
    26		pgURL := os.Getenv("DATABASE_URL")
    27		if pgURL == "" {
    28			pgURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
    29		}
    30		pg, err := pgxpool.New(ctx, pgURL)
    31		if err != nil {
    32			return nil, fmt.Errorf("pg: %w", err)
    33		}
    34		if err := pg.Ping(ctx); err != nil {
    35			return nil, fmt.Errorf("pg ping: %w", err)
    36		}
    37	
    38		mongoURI := os.Getenv("MONGODB_URI")
    39		if mongoURI == "" {
    40			mongoURI = "mongodb://127.0.0.1:27017/arena"
    41		}
    42		mc, err := mongo.Connect(options.Client().ApplyURI(mongoURI))
    43		if err != nil {
    44			return nil, fmt.Errorf("mongo: %w", err)
    45		}
    46		if err := mc.Ping(ctx, nil); err != nil {
    47			return nil, fmt.Errorf("mongo ping: %w", err)
    48		}
    49		dbName := "arena"
    50		if i := strings.LastIndex(mongoURI, "/"); i >= 0 {
    51			rest := mongoURI[i+1:]
    52			if q := strings.Index(rest, "?"); q >= 0 {
    53				rest = rest[:q]
    54			}
    55			if rest != "" {
    56				dbName = rest
    57			}
    58		}
    59		return &Store{
    60			PG:    pg,
    61			Mongo: mc,
    62			Audit: mc.Database(dbName).Collection("audit_entries"),
    63		}, nil
    64	}
