    90	func (s *Store) MaterializeMongo(ctx context.Context) error {
    91		db := s.Audit.Database()
    92		names := []string{"audit_entries", "realtime_events"}
    93		existing, _ := db.ListCollectionNames(ctx, bson.M{})
    94		have := map[string]bool{}
    95		for _, n := range existing {
    96			have[n] = true
    97		}
    98		for _, n := range names {
    99			if !have[n] {
   100				_ = db.CreateCollection(ctx, n)
   101			}
   102		}
   103		_, _ = db.Collection("audit_entries").Indexes().CreateMany(ctx, []mongo.IndexModel{
   104			{Keys: bson.D{{Key: "auditId", Value: 1}}, Options: options.Index().SetUnique(true)},
   105			{Keys: bson.D{{Key: "actorId", Value: 1}, {Key: "occurredAt", Value: -1}}},
   106			{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}, {Key: "occurredAt", Value: -1}}},
   107			{Keys: bson.D{{Key: "action", Value: 1}, {Key: "occurredAt", Value: -1}}},
   108			{Keys: bson.D{{Key: "role", Value: 1}}},
   109			{Keys: bson.D{{Key: "success", Value: 1}}},
   110			{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
   111		})
   112		_, _ = db.Collection("realtime_events").Indexes().CreateMany(ctx, []mongo.IndexModel{
   113			{Keys: bson.D{{Key: "id", Value: 1}}},
   114			{Keys: bson.D{{Key: "createdAt", Value: -1}}},
   115		})
   116		return nil
   117	}
