   119	func (s *Store) Reset(ctx context.Context, schemaSQL string) error {
   120		// Drop all application tables
   121		tables := []string{
   122			"realtime_events", "meta", "serviceability_snapshots", "disruptions",
   123			"idempotency", "timeline", "worker_locations", "checkpoints", "handoffs",
   124			"capacity_reservations", "assignments", "journey_stops", "journey_samples",
   125			"journeys", "samples", "connections", "laboratory_acceptance", "locations",
   126			"sample_types", "sessions", "certifications", "users",
   127		}
   128		for _, t := range tables {
   129			if _, err := s.PG.Exec(ctx, "DROP TABLE IF EXISTS "+t+" CASCADE"); err != nil {
   130				return fmt.Errorf("drop %s: %w", t, err)
   131			}
   132		}
   133		if err := s.ApplySchema(ctx, schemaSQL); err != nil {
   134			return err
   135		}
   136		// Mongo
   137		_ = s.Audit.Database().Collection("audit_entries").Drop(ctx)
   138		_ = s.Audit.Database().Collection("realtime_events").Drop(ctx)
   139		if err := s.MaterializeMongo(ctx); err != nil {
   140			return err
   141		}
   142		return seedDefaultSampleTypes(ctx, s)
   143	}
