   202	func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
   203		auth := getAuth(r)
   204		if !roleSelected(auth) {
   205			writeErr(w, 409, "role_not_selected", "select a role")
   206			return
   207		}
   208		var req struct {
   209			SampleID         string `json:"sampleId"`
   210			FromAssignmentID string `json:"fromAssignmentId"`
   211			ToAssignmentID   string `json:"toAssignmentId"`
   212			IdempotencyKey   string `json:"idempotencyKey"`
   213		}
   214		if err := decodeJSON(r, &req); err != nil {
   215			writeErr(w, 400, "invalid_json", "invalid json")
   216			return
   217		}
   218		sid, err := uuid.Parse(req.SampleID)
   219		if err != nil {
   220			writeErr(w, 404, "not_found", "not found")
   221			return
   222		}
   223		fromID, err1 := uuid.Parse(req.FromAssignmentID)
   224		toID, err2 := uuid.Parse(req.ToAssignmentID)
   225		if err1 != nil || err2 != nil {
   226			writeErr(w, 400, "invalid_json", "invalid assignment")
   227			return
   228		}
   229		sm, _ := app.Store.GetSample(r.Context(), sid)
   230		if sm == nil {
   231			writeErr(w, 404, "not_found", "sample")
   232			return
   233		}
   234		if sm.CurrentHolderID == nil || *sm.CurrentHolderID != auth.User.ID {
   235			writeErr(w, 409, "not_current_holder", "not current holder")
   236			return
   237		}
   238		from, _ := app.Store.GetAssignment(r.Context(), fromID)
   239		to, _ := app.Store.GetAssignment(r.Context(), toID)
   240		if from == nil || to == nil || from.SampleID != sid || to.SampleID != sid {
   241			writeErr(w, 409, "invalid_handoff_pair", "invalid pair")
   242			return
   243		}
   244		if from.WorkerID == nil || *from.WorkerID != auth.User.ID {
   245			writeErr(w, 409, "invalid_handoff_pair", "sender not on from assignment")
   246			return
   247		}
   248		if to.WorkerID == nil {
   249			writeErr(w, 409, "invalid_handoff_pair", "receiver not accepted")
   250			return
   251		}
   252		if from.Sequence >= to.Sequence {
   253			writeErr(w, 409, "invalid_handoff_pair", "not sequential")
   254			return
   255		}
   256		if sm.PendingHandoffID != nil {
   257			// idempotent-ish: return existing
   258			h, _ := app.Store.GetHandoff(r.Context(), *sm.PendingHandoffID)
   259			if h != nil && h.FromAssignmentID == fromID && h.ToAssignmentID == toID {
   260				writeData(w, 201, handoffPayload(*h))
   261				return
   262			}
   263			writeErr(w, 409, "handoff_already_pending", "already pending")
   264			return
   265		}
   266		now := time.Now().UTC()
   267		h := Handoff{
   268			ID: uuid.New(), SampleID: sid, FromAssignmentID: fromID, ToAssignmentID: toID,
   269			SenderID: auth.User.ID, ReceiverID: *to.WorkerID, Status: "pending",
   270			SenderConfirmed: false, ReceiverConfirmed: false, InitiatedAt: now,
   271		}
   272		if err := app.Store.InsertHandoff(r.Context(), h); err != nil {
   273			writeErr(w, 500, "internal_error", "insert")
   274			return
   275		}
   276		sm.PendingHandoffID = &h.ID
   277		_ = app.Store.UpdateSample(r.Context(), *sm)
   278		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "initiate_handoff", "sample", sid.String(), true, map[string]interface{}{"handoffId": h.ID.String()})
   279		writeData(w, 201, handoffPayload(h))
   280	}
   281	
   282	func handoffPayload(h Handoff) map[string]any {
   283		return map[string]any{
   284			"handoffId":         h.ID.String(),
   285			"sampleId":          h.SampleID.String(),
   286			"fromAssignmentId":  h.FromAssignmentID.String(),
   287			"toAssignmentId":    h.ToAssignmentID.String(),
   288			"status":            h.Status,
   289			"senderConfirmed":   h.SenderConfirmed,
   290			"receiverConfirmed": h.ReceiverConfirmed,
   291		}
   292	}
