   331			}
   332			h.SenderConfirmed = true
   333		} else {
   334			if h.ReceiverID != auth.User.ID {
   335				writeErr(w, 403, "forbidden", "not receiver")
   336				return
   337			}
   338			h.ReceiverConfirmed = true
   339		}
   340		if h.SenderConfirmed && h.ReceiverConfirmed {
