   595	func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
   596		auth := getAuth(r)
   597		if !roleSelected(auth) {
   598			writeErr(w, 409, "role_not_selected", "select a role")
   599			return
   600		}
   601		var req struct {
   602			Role string `json:"role"`
   603		}
   604		_ = json.NewDecoder(r.Body).Decode(&req)
   605		role := auth.ActiveRole
   606		if req.Role != "" {
   607			if req.Role != auth.ActiveRole {
   608				writeErr(w, 403, "forbidden", "role must match active role")
   609				return
   610			}
   611			role = req.Role
   612		}
   613		now := time.Now().UTC()
   614		var pending, inProg, completed []map[string]any
   615	
   616		switch role {
   617		case RoleRequester:
   618			samples, _ := app.Store.ListSamplesByRequester(r.Context(), auth.User.ID)
   619			for _, sm := range samples {
   620				item := app.sampleWorkItem(r.Context(), sm, now)
   621				switch {
   622				case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
   623					completed = append(completed, item)
   624				case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
   625					pending = append(pending, item)
   626				default:
   627					inProg = append(inProg, item)
   628				}
   629			}
   630		case RoleAdministrator, RoleDispatcher:
   631			samples, _ := app.Store.ListSamples(r.Context())
   632			for _, sm := range samples {
   633				item := app.sampleWorkItem(r.Context(), sm, now)
   634				switch {
   635				case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
   636					completed = append(completed, item)
   637				case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
   638					pending = append(pending, item)
   639				default:
   640					inProg = append(inProg, item)
   641				}
   642			}
   643		default:
   644			asgs, _ := app.Store.ListAssignmentsForWorker(r.Context(), auth.User.ID)
   645			for _, a := range asgs {
   646				// filter by role kind
   647				if !assignmentMatchesRole(a.Kind, role) {
   648					continue
   649				}
   650				item := app.assignmentWorkItem(r.Context(), a)
   651				switch a.Status {
   652				case StatusCompleted, StatusCancelled:
   653					completed = append(completed, item)
   654				case StatusAccepted, StatusInProgress:
   655					inProg = append(inProg, item)
   656				default:
   657					pending = append(pending, item)
   658				}
   659			}
   660		}
   661		if pending == nil {
   662			pending = []map[string]any{}
   663		}
   664		if inProg == nil {
   665			inProg = []map[string]any{}
   666		}
   667		if completed == nil {
   668			completed = []map[string]any{}
   669		}
   670		writeData(w, 200, map[string]any{
   671			"role":              role,
   672			"pending":           pending,
   673			"inProgress":        inProg,
   674			"completed":         completed,
   675			"current":           append(append([]map[string]any{}, pending...), inProg...),
   676			"past":              completed,
   677		})
   678	}
   679	
   680	func assignmentMatchesRole(kind, role string) bool {
   681		switch role {
   682		case RoleCollectionProfessional:
   683			return kind == KindCollection
   684		case RoleDeliveryPartner:
   685			return kind == KindTransport
   686		case RoleNodeHandler:
   687			return kind == KindNode
   688		case RoleLaboratoryTeam:
   689			return kind == KindLaboratory
   690		}

