   791		} else if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
   792			writeErr(w, 400, "invalid_origin_type", "invalid origin type")
   793			return
   794		}
   795		stID, err := uuid.Parse(req.SampleTypeID)
   796		if err != nil {
   797			writeErr(w, 404, "not_found", "sample type")
   798			return
   799		}
   800		st, _ := app.Store.GetSampleType(r.Context(), stID)
   801		if st == nil {
   802			writeErr(w, 404, "not_found", "sample type")
   803			return
   804		}
   805		if req.ContainerType == "" || req.TemperatureMinC > req.TemperatureMaxC {
   806			writeErr(w, 400, "handling_mismatch", "invalid handling")
   807			return
   808		}
   809		// optional match against type
