   819		if err != nil {
   820			writeErr(w, 400, "invalid_deadline", "invalid deadline")
   821			return
   822		}
   823		if !deadline.After(requestedAt) {
   824			writeErr(w, 400, "invalid_deadline", "deadline must be after requestedAt")
   825			return
   826		}
   827		earliest, latest := requestedAt, deadline
   828		if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
   829			t, err := parseTime(*req.EarliestCollectionAt)
   830			if err != nil {
