   838			if err != nil {
   839				writeErr(w, 400, "invalid_time", "invalid latest")
   840				return
   841			}
   842			latest = t
   843		}
   844		if latest.Before(earliest) {
   845			writeErr(w, 400, "invalid_collection_window", "invalid window")
   846			return
   847		}
   848		var nodeID *uuid.UUID
