   898			IncompatibleSampleTypes: incomp,
   899			Serviceability: "unserviceable", ServiceabilityReason: res.Reason,
   900			Status: StatusUnserviceable, AlreadySealed: presealed,
   901			LatestLat: &req.Origin.Latitude, LatestLng: &req.Origin.Longitude,
   902		}
   903		now := time.Now().UTC()
   904		sm.LocationRecordedAt = &now
   905		if res.Serviceable {
   906			sm.Serviceability = "serviceable"
   907			sm.Status = StatusRequested
