   912			return
   913		}
   914		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_request", "sample", sm.ID.String(), true, map[string]interface{}{"presealed": presealed})
   915	
   916		var activeIDs []string
   917		var journeyID *uuid.UUID
   918		if res.Serviceable && res.Route != nil {
   919			if presealed {
   920				sm.CurrentHolderID = &auth.User.ID
   921				sm.Sealed = true
   922				sm.SealedAt = &now
   923				sm.AlreadySealed = true
   924				sm.Status = StatusSealed
   925			}
   926			j, asgs, err := app.materializeJourney(r.Context(), &sm, st, res, presealed, auth.User.ID.String(), auth.ActiveRole)
   927			if err != nil {
   928				// keep sample as unserviceable if planning fails due to capacity etc.
