   113			if err := cur.Decode(&raw); err != nil {
   114				continue
   115			}
   116			entries = append(entries, normalizeAudit(raw))
   117		}
   118		if entries == nil {
   119			entries = []map[string]any{}
   120		}
   121		_ = strings.TrimSpace
   122		return entries, int(total), nil
   123	}
