    96			Username           string          `json:"username"`
    97			InitialPassword    string          `json:"initialPassword"`
    98			Email              string          `json:"email"`
    99			FullName           string          `json:"fullName"`
   100			Phone              string          `json:"phone"`
   101			Roles              []string        `json:"roles"`
   102			Qualifications     []string        `json:"qualifications"`
   103			Certifications     []Certification `json:"certifications"`
   104			Active             bool            `json:"active"`
   105			AssignedLocationID *string         `json:"assignedLocationId"`
   106		}
   107		if err := decodeJSON(r, &req); err != nil {
   108			writeErr(w, 400, "invalid_json", "invalid json")
   109			return
   110		}
   111		if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
   112			writeErr(w, 400, "invalid_user", "invalid user")
   113			return
   114		}
   115		for _, role := range req.Roles {
   116			if !validRole(role) {
   117				writeErr(w, 400, "invalid_user", "invalid role")
   118				return
   119			}
   120		}
   121		if existing, _ := app.Store.GetUserByUsername(r.Context(), req.Username); existing != nil {
   122			writeErr(w, 409, "username_exists", "username exists")
   123			return
   124		}
   125		hash, err := bcrypt.GenerateFromPassword([]byte(req.InitialPassword), bcrypt.DefaultCost)
   126		if err != nil {
   127			writeErr(w, 500, "internal_error", "hash")
   128			return
   129		}
   130		var loc *uuid.UUID
   131		if req.AssignedLocationID != nil && *req.AssignedLocationID != "" {
   132			id, err := uuid.Parse(*req.AssignedLocationID)
   133			if err != nil {
   134				writeErr(w, 400, "invalid_user", "invalid assigned location")
   135				return
   136			}
   137			loc = &id
   138		}
   139		if req.Qualifications == nil {
   140			req.Qualifications = []string{}
   141		}
   142		if req.Certifications == nil {
   143			req.Certifications = []Certification{}
   144		}
   145		for _, c := range req.Certifications {
   146			if c.Code == "" {
   147				writeErr(w, 400, "invalid_certification", "invalid certification")
   148				return
   149			}
   150		}
