   153			Email: req.Email, FullName: req.FullName, Phone: req.Phone,
   154			Roles: req.Roles, Qualifications: req.Qualifications, AssignedLocationID: loc,
   155			Active: req.Active, Available: true, CapacityUnits: 1,
   156		}
   157		if err := app.Store.InsertUser(r.Context(), u); err != nil {
