   165		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_user", "user", u.ID.String(), true, map[string]interface{}{"username": u.Username})
   166		writeData(w, 201, userPayload(u, req.Certifications))
