   177			"userId":          u.ID.String(),
   178			"username":        u.Username,
   179			"roles":           u.Roles,
   180			"qualifications":  u.Qualifications,
   181			"certifications":  certs,
   182			"active":          u.Active,
   183		}
   184		if u.Email != "" {
   185			m["email"] = u.Email
   186		}
   187		if u.FullName != "" {
   188			m["fullName"] = u.FullName
   189		}
