  1680	func (app *App) handleMerge(w http.ResponseWriter, r *http.Request) {
  1681		auth := getAuth(r)
  1682		if !roleSelected(auth) {
  1683			writeErr(w, 409, "role_not_selected", "select a role")
  1684			return
  1685		}
  1686		if !adminOrDispatcher(auth) {
  1687			writeErr(w, 403, "forbidden", "forbidden")
  1688			return
  1689		}
  1690		var req struct {
  1691			JourneyIDs          []string `json:"journeyIds"`
  1692			ExpectedPlanVersions []int   `json:"expectedPlanVersions"`
  1693			IdempotencyKey      string   `json:"idempotencyKey"`
  1694		}
  1695		if err := decodeJSON(r, &req); err != nil {
  1696			writeErr(w, 400, "invalid_json", "invalid json")
  1697			return
  1698		}
  1699		if len(req.JourneyIDs) < 2 {
  1700			writeErr(w, 400, "invalid_json", "need at least two journeys")
  1701			return
  1702		}
  1703		var journeys []Journey
  1704		var samples []Sample
  1705		for i, js := range req.JourneyIDs {
  1706			id, err := uuid.Parse(js)
  1707			if err != nil {
  1708				writeErr(w, 404, "not_found", "not found")
  1709				return
  1710			}
  1711			j, _ := app.Store.GetJourney(r.Context(), id)
  1712			if j == nil {
  1713				writeErr(w, 404, "not_found", "not found")
  1714				return
  1715			}
  1716			if i < len(req.ExpectedPlanVersions) && req.ExpectedPlanVersions[i] != j.PlanVersion {
  1717				writeErr(w, 409, "stale_plan", "stale plan")
  1718				return
  1719			}
  1720			journeys = append(journeys, *j)
  1721			sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
  1722			for _, sid := range sids {
  1723				sm, _ := app.Store.GetSample(r.Context(), sid)
  1724				if sm != nil {
  1725					samples = append(samples, *sm)
  1726				}
  1727			}
  1728		}
  1729		// compatibility
  1730		if !compatibleBatch(samples) {
  1731			writeErr(w, 409, "incompatible_batch", "samples cannot travel together")
  1732			return
  1733		}
  1734		primary := journeys[0]
  1735		primary.PlanVersion++
  1736		primary.RouteMode = RouteBatched
  1737		_ = app.Store.UpdateJourney(r.Context(), primary)
  1738		for i := 1; i < len(journeys); i++ {
  1739			sids, _ := app.Store.JourneySampleIDs(r.Context(), journeys[i].ID)
  1740			for _, sid := range sids {
  1741				_ = app.Store.AddJourneySample(r.Context(), primary.ID, sid)
  1742				sm, _ := app.Store.GetSample(r.Context(), sid)
  1743				if sm != nil {
  1744					sm.ActiveJourneyID = &primary.ID
  1745					_ = app.Store.UpdateSample(r.Context(), *sm)
  1746				}
  1747			}
  1748			journeys[i].Status = StatusCancelled
  1749			journeys[i].PlanVersion++
  1750			_ = app.Store.UpdateJourney(r.Context(), journeys[i])
  1751		}
  1752		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "merge_journeys", "journey", primary.ID.String(), true, nil)
  1753		writeData(w, 200, map[string]any{"journeyId": primary.ID.String(), "planVersion": primary.PlanVersion, "routeMode": primary.RouteMode})
  1754	}
