   264			mux.HandleFunc("/", spaHandler(webDir))
   265		} else {
   266			mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
   267				if r.URL.Path == "/" {
   268					w.Header().Set("Content-Type", "text/plain")
   269					_, _ = w.Write([]byte("Lab Sample Pickup & Delivery API"))
   270					return
   271				}
