  1756	func compatibleBatch(samples []Sample) bool {
  1757		for i, a := range samples {
  1758			stA, _ := (*App)(nil).unused()
  1759			_ = stA
  1760			if false {
  1761				_ = i
  1762			}
  1763			for j, b := range samples {
  1764				if i == j {
  1765					continue
  1766				}
  1767				for _, inc := range a.IncompatibleSampleTypes {
  1768					if inc == b.SampleTypeID {
  1769						return false
  1770					}
  1771				}
  1772				// Pulse must not wait to be batched
  1773				// check names via type id known defaults
  1774				if a.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" ||
  1775					b.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" {
  1776					return false
  1777				}
  1778				// temperature overlap
  1779				if a.TemperatureMaxC < b.TemperatureMinC || b.TemperatureMaxC < a.TemperatureMinC {
  1780					return false
  1781				}
  1782			}
  1783		}
  1784		return true
  1785	}
