   149				Name: "Amber", QualifiedCollectorRequired: true, RequiredQualification: "Amber",
   150				ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 30,
   151				RequiresCooledRoute: false, BatchingAllowed: true,
   152			},
   153			{
   154				ID: uuid.MustParse("aaaaaaaa-0001-4000-8000-000000000002"),
   155				Name: "Indigo", QualifiedCollectorRequired: true, RequiredQualification: "Indigo",
   156				ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 30,
   157				IncompatibleSampleTypes: []uuid.UUID{uuid.MustParse("aaaaaaaa-0001-4000-8000-000000000001")},
   158				RequiresCooledRoute: false, BatchingAllowed: true,
   159			},
   160			{
   161				ID: uuid.MustParse("aaaaaaaa-0001-4000-8000-000000000003"),
   162				Name: "Frost", QualifiedCollectorRequired: true, RequiredQualification: "Frost",
   163				ContainerType: "cooled", TemperatureMinC: 2, TemperatureMaxC: 8,
   164				RequiresCooledRoute: true, BatchingAllowed: true,
   165			},
   166			{
   167				ID: uuid.MustParse("aaaaaaaa-0001-4000-8000-000000000004"),
   168				Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "Pulse",
   169				ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 30,
   170				RequiresCooledRoute: false, BatchingAllowed: false,
   171			},
   172		}
   173		for _, st := range defaults {
   174			if err := s.InsertSampleType(ctx, st); err != nil {
   175				return err
   176			}
   177		}
   178		// initial empty complete snapshot
   179		_, _ = s.PG.Exec(ctx, `
   180			INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, payload)
   181			VALUES (1, 'complete', now(), 1, '{"regions":[]}'::jsonb)
   182			ON CONFLICT DO NOTHING`)
   183		return nil
   184	}
