   812	func (app *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
   813		auth := getAuth(r)
   814		if !roleSelected(auth) {
   815			writeErr(w, 409, "role_not_selected", "select a role")
   816			return
   817		}
   818		// admin always; node handler / lab team for their assigned location
   819		var req struct {
   820			ResourceID          string `json:"resourceId"`
   821			CapacityUnits       int    `json:"capacityUnits"`
   822			CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
   823		}
   824		if err := decodeJSON(r, &req); err != nil {
   825			writeErr(w, 400, "invalid_json", "invalid json")
   826			return
   827		}
   828		if req.CapacityUnits < 0 {
   829			writeErr(w, 400, "invalid_capacity", "invalid capacity")
   830			return
   831		}
   832		cooled := 0
   833		if req.CooledCapacityUnits != nil {
   834			if *req.CooledCapacityUnits < 0 {
   835				writeErr(w, 400, "invalid_capacity", "invalid cooled capacity")
   836				return
   837			}
   838			cooled = *req.CooledCapacityUnits
   839		}
   840		rid, err := uuid.Parse(req.ResourceID)
   841		if err != nil {
   842			writeErr(w, 400, "invalid_json", "invalid resource")
   843			return
   844		}
   845		loc, _ := app.Store.GetLocation(r.Context(), rid)
   846		conn, _ := app.Store.GetConnection(r.Context(), rid)
   847		if loc == nil && conn == nil {
   848			writeErr(w, 400, "invalid_capacity", "unknown resource")
   849			return
   850		}
   851		allowed := requireRole(auth, RoleAdministrator)
   852		if !allowed && requireRole(auth, RoleNodeHandler, RoleLaboratoryTeam) {
   853			if loc != nil && auth.User.AssignedLocationID != nil && *auth.User.AssignedLocationID == loc.ID {
   854				allowed = true
   855			}
   856		}
   857		if !allowed {
   858			writeErr(w, 403, "forbidden", "forbidden")
   859			return
   860		}
   861		// refuse reducing below reserved
   862		if loc != nil {
   863			if req.CapacityUnits < loc.ReservedUnits || cooled < loc.CooledReserved {
   864				writeErr(w, 409, "capacity_reserved", "capacity reserved")
   865				return
